YH_EXAM_BANKS["MGT102-CH5"] = {"id":"MGT102-CH5","short":"الفصل الخامس","version":1,"los":[{"lo":"LO5-1","en":"Discuss the increasing diversity of the workforce and the organizational environment.","ar":"التنوّع المتزايد في القوى العاملة والبيئة"},{"lo":"LO5-2","en":"Explain the central role that managers play in the effective management of diversity.","ar":"دور المدير المحوري في إدارة التنوّع"},{"lo":"LO5-3","en":"Explain why the effective management of diversity is both an ethical and a business imperative.","ar":"ليش إدارة التنوّع واجب أخلاقي وتجاري"},{"lo":"LO5-4","en":"Discuss how perception and the use of schemas can result in unfair treatment.","ar":"الإدراك والـschemas والمعاملة غير العادلة"},{"lo":"LO5-5","en":"List the steps managers can take to manage diversity effectively.","ar":"خطوات المدير لإدارة التنوّع بفعالية"},{"lo":"LO5-6","en":"Identify the two major forms of sexual harassment and how they can be eliminated.","ar":"شكلا التحرّش الجنسي وطرق القضاء عليه"}],"sections":{"MGT102-CH5-S1":{"ar":"التنوّع المتزايد في القوى العاملة","en":"The Increasing Diversity of the Workforce"},"MGT102-CH5-S2":{"ar":"دور المدير في إدارة التنوّع","en":"Managers and the Effective Management of Diversity"},"MGT102-CH5-S3":{"ar":"الإدراك والمعاملة غير العادلة","en":"Perception and Unfair Treatment"},"MGT102-CH5-S4":{"ar":"كيف تدير التنوّع والتحرّش الجنسي","en":"Managing Diversity Effectively and Sexual Harassment"}},"misconceptions":[{"id":"c5.diversity-sources","ar":"تحصر التنوّع أو تغلط في مصادره","explain":"تحسب إن diversity بس العرق والجنس أو الصفات اللي يحميها القانون، والتعريف ينتهي بـany other characteristic ويدخل فيه education وexperience وphysical appearance. وFigure 5.1 فيه ١٢ قطعة (Race وEthnicity كل وحدة لحالها)، وpersonality أو salary أو job performance مو منها.","fix":"ارجع لبلوك «Diversity and the Sources of Diversity» في درس ١، وعدّ قطع Figure 5.1 بصوت عالي لين تطلع ١٢، وبعدين كرت C5S1-c-figure-5-1 وC5S1-c-diversity في كروت القسم.","sec":"MGT102-CH5-S1","coach":"خلّه يسمّع لك الـ١٢ قطعة حقّت Figure 5.1 بالإنجليزي وهو مغمّض، وبعدين اسأله بسرعة: personality منها؟ education منها؟ لين يجاوب بدون تردّد."},{"id":"c5.hiring-is-enough","ar":"تحسب توظيف المتنوّعين يكفي لإدارة التنوّع","explain":"تختار إن إدارة التنوّع يعني بس توظّف ناس متنوّعين، أو إن وجود diverse workforce يضمن أداء أعلى. الكتاب يقول simply having a diverse workforce may not guarantee higher performance، والمطلوب إنهم included and heard مو بس recruited and hired.","fix":"ارجع لبلوكَي «Diversity and the Sources of Diversity» و«Why Diversity Is a Pressing Concern and the Glass Ceiling» في درس ١ واقرأ الفخ عن عبارة الـNFL، وبعدين كرت C5S1-c-managing-diversity.","sec":"MGT102-CH5-S1","coach":"قل له: «عندي فريق متنوّع، يعني أدائي بيرتفع أكيد؟» وخلّه يرد بعبارة may not guarantee، ويكمّل وش اللازم بعد التوظيف (included and heard)."},{"id":"c5.glass-ceiling","ar":"تغلط في تعريف السقف الزجاجي","explain":"Glass ceiling = invisible barriers (مو قوانين ولا سياسات مكتوبة) تمنع women and minorities — مو النساء بس — من الترقية لـtop corporate positions، وحالته الحين beginning to crack مو انتهى. لا تخلطه مع overt discrimination (ظلم متعمّد وواضح) ولا مع gender wage gap (فجوة الأجر).","fix":"ارجع لبلوك «Why Diversity Is a Pressing Concern and the Glass Ceiling» في درس ١ واقرأ الفخ، وبعدين كرت C5S1-c-glass-ceiling.","sec":"MGT102-CH5-S1","coach":"اسأله ثلاث أسئلة ورا بعض: الحاجز مكتوب ولا مخفي؟ يمنع مين بالضبط؟ يمنعهم من وش؟ لازم يقول invisible وwomen and minorities وtop corporate positions."},{"id":"c5.race-ethnicity-ses","ar":"تخلط بين العرق والإثنية والخلفية الاجتماعية-الاقتصادية","explain":"Ethnicity = a grouping of people based on some shared characteristic زي national origin, language, or culture، أما race ففئات التعداد. وsocioeconomic background = a combination of social class and income-related factors — مو التعليم ولا العرق.","fix":"ارجع لبلوك «Age, Gender, Race, and Ethnicity» وبلوك «Religion, Capabilities/Disabilities, Socioeconomic Background…» في درس ١، وبعدين كروت C5S1-c-race-ethnicity وC5S1-c-socioeconomic-background.","sec":"MGT102-CH5-S1","coach":"قل له الكلمة المفتاحية وهو يرد بالمصطلح: «language and culture» ← ethnicity، «social class and income» ← socioeconomic background، وبدّل الترتيب لين يصير تلقائي."},{"id":"c5.eeo-law-year","ar":"تبدّل القوانين وسنواتها في Table 5.1","explain":"تربط القانون بسنة غلط: 1963 Equal Pay · 1964 Title VII · 1967 ADEA · 1978 Pregnancy · 1990 ADA · 1991 Civil Rights Act · 1993 FMLA · 1994 USERRA. أشهر قلب 1963 مع 1964، و1964 مع 1991 لأن الاثنين اسمهم Civil Rights Act.","fix":"ارجع لبلوك «Major Equal Employment Opportunity Laws» في درس ١، غطِّ عمود Year في Table 5.1 وسمّعه، وبعدين كرت C5S1-c-table-5-1.","sec":"MGT102-CH5-S1","coach":"قل السنة وهو يقول القانون (1990 ← ADA)، وبعدين اعكسها، جولتين؛ ركّز على 1963/1964 و1964/1991 لأنها اللي تنقلب عنده."},{"id":"c5.eeo-law-coverage","ar":"تعطي القانون حماية مو حقّته","explain":"Title VII أسسه خمسة بس (race, religion, sex, color, national origin)، فالعمر لـADEA (فوق 40) والإعاقة لـADA، وFMLA عطلة 12 أسبوع unpaid، وCivil Rights Act 1991 يضيف punitive and compensatory damages. وتسهيلات الأعياد الدينية جاية من إرشادات البيت الأبيض 1997 بشرط ما تكلّف كثير، مو صف في الجدول.","fix":"ارجع لعمود Description في Table 5.1 (بلوك «Major Equal Employment Opportunity Laws») واقرأ الفخ، وفقرة reasonable accommodations في بلوك الدين والإعاقة، وبعدين كرت C5S1-c-reasonable-accommodations.","sec":"MGT102-CH5-S1","coach":"اسأله: مين يحمي من التمييز بسبب العمر؟ والحمل؟ والإعاقة؟ ووش اللي يميّز قانون 1991؟ ولو قال Title VII للعمر وقّفه وخلّه يعدّ أسسه الخمسة."},{"id":"c5.role-type-count","ar":"تحط الدور في نوع غلط من الثلاثة","explain":"أدوار Table 5.2 عشرة = 3 interpersonal (figurehead, leader, liaison) + 3 informational (monitor, disseminator, spokesperson) + 4 decisional (entrepreneur, disturbance handler, resource allocator, negotiator). الغلط إنك تحط liaison مع المعلوماتية أو monitor مع القرارية، أو تقول العدد غير ١٠.","fix":"ارجع لبلوك «Critical Managerial Roles» في درس ٢ وغطِّ عمود Specific Role في Table 5.2، وبعدين كروت C5S2-c-managerial-roles وC5S2-c-interpersonal-roles وC5S2-c-informational-roles.","sec":"MGT102-CH5-S2","coach":"قل له اسم الدور وخلّه يرد بنوعه بس (interpersonal / informational / decisional)، وبعدين اسأله: كم دور في كل نوع؟ لازم يقول 3-3-4."},{"id":"c5.entrepreneur-vs-allocator","ar":"تخلط بين entrepreneur و resource allocator","explain":"الاثنين فيهم موارد: entrepreneur commits resources to develop new ways (يبتكر طرق جديدة لإدارة التنوّع ويشيل التحيّز)، وresource allocator allocates resources to support and encourage (يوزّع موارد يدعم فيها). الكلمة اللي تفرّق new ways.","fix":"ارجع لصفوف Decisional في Table 5.2 داخل بلوك «Critical Managerial Roles» بدرس ٢ واقرأ الفخ، وبعدين كرت C5S2-c-entrepreneur-vs-allocator.","sec":"MGT102-CH5-S2","coach":"أعطه موقفين: «مدير خصّص ميزانية يطوّر برنامج جديد يكشف التحيّز» و«مدير وزّع الميزانية على مبادرات التنوّع الموجودة»، وخلّه يسمّي الدور ويقول الكلمة اللي فرّقت."},{"id":"c5.role-duty-mix","ar":"تخلط بين مهام الأدوار المتشابهة في Table 5.2","explain":"تحط role model تحت figurehead وهي للـleader (الـfigurehead بس يوصّل إن التنوّع valued goal). وفي المعلوماتية: monitor يقيّم العدالة، disseminator يبلّغ الموظفين جوّا، spokesperson يتكلّم للمجتمع برّا، والـnegotiator يشتغل مع suppliers وlabor unions مو مع الموظفين.","fix":"ارجع لعمود Example في Table 5.2 (بلوك «Critical Managerial Roles» درس ٢)، غطِّ اسم الدور واقرأ المثال وخمّن، وبعدين كرت C5S2-c-informational-roles وC5S2-c-interpersonal-roles.","sec":"MGT102-CH5-S2","coach":"اقرأ له جملة من عمود Example بالإنجليزي وخلّه يقول اسم الدور؛ ركّز على الأزواج figurehead/leader وmonitor/disseminator/spokesperson."},{"id":"c5.small-differences","ar":"تحسب الفروق الصغيرة في المعاملة تختفي مع الوقت","explain":"الكتاب يقول slight differences in treatment can accumulate and result in major disparities over time، يعني العيب البسيط في البداية يكبر لو انترك مو يختفي. وتأثير المدير جاي من formal authority والـhigh status (social influence)، مو من إنه أغلبية.","fix":"ارجع لبلوك «Why Managers Are Central to Diversity» في درس ٢ واقرأ الفخ، وبعدين كروت C5S2-c-two-factors وC5S2-c-formal-authority وC5S2-c-manager-commitment.","sec":"MGT102-CH5-S2","coach":"اسأله: «موظفة ترقيتها تتأخر شوي كل مرة، وش يصير بعد عشر سنين؟» وخلّه يجاوب بـaccumulate وmajor disparities، وبعدها: ليش الموظفين يقلّدون المدير؟"},{"id":"c5.distributive-vs-procedural","ar":"تخلط بين distributive justice و procedural justice","explain":"Distributive = عدالة النتيجة نفسها: مين ياخذ pay وpromotions وjob titles وoffice space. Procedural = عدالة الطريقة: fair procedures تقرّر التوزيع زي تقييم الأداء ومين يترقّى ومين ينفصل؛ «كيف قرّرنا» ← procedural، «وش أخذ» ← distributive.","fix":"ارجع لبلوكَي «Distributive Justice» و«Procedural Justice» في درس ٢ واقرأ الفخين، وبعدين كروت C5S2-c-distributive-justice وC5S2-c-procedural-justice.","sec":"MGT102-CH5-S2","coach":"أعطه مواقف سريعة («الترقية راحت لأضعف واحد أداء» / «التقييم صار بدون ما يحسب عطل المكينة») وخلّه يقول outcome ولا procedure قبل ما يسمّي المبدأ."},{"id":"c5.distributive-equal-outcomes","ar":"تحسب العدالة التوزيعية يعني الكل ياخذ نفس الشي","explain":"Distributive justice مو مساواة مطلقة: الكتاب يقول does not mean that all members receive identical or similar outcomes. التوزيع حسب meaningful contributions (time, effort, education, skills, performance)، مو حسب صفات ما لك يد فيها زي gender, race, age.","fix":"ارجع لبلوك «Distributive Justice» في درس ٢ واقرأ EXAM BOX والفخ، وبعدين كرت C5S2-c-distributive-justice.","sec":"MGT102-CH5-S2","coach":"اسأله: «موظف ياخذ أكثر من زميله، هذا ظلم؟» لازم يقول «يعتمد على المساهمة»، وبعدين خلّه يعدّد مساهمتين مقبولة وصفتين ممنوعة."},{"id":"c5.ethical-vs-business","ar":"تخلط بين الحجة الأخلاقية والحجة التجارية للتنوّع","explain":"الحجة الأخلاقية مبنية على مبدأين بس: distributive وprocedural justice (مو القواعد الأربع حقّت الفصل ٤). والتجارية: competitive advantage وقرارات وإبداع أحسن، خدمة عملاء متنوّعين، retention (البديل يكلّف ضعفين الراتب)، موردين يدعمون التنوّع، وتجنّب lawsuits زي Coca-Cola $192 million.","fix":"ارجع لبلوك «Managing Diversity Makes Good Business Sense» في درس ٢ وقارنه ببلوكَي العدالة، وبعدين كرت C5S2-c-business-sense.","sec":"MGT102-CH5-S2","coach":"خلّه يقسم ورقة نصّين أخلاقي وتجاري، واقرأ له أسباب متفرقة (retention، fair procedures، IKEA، suppliers) وهو يحطها في مكانها؛ وذكّره إن الدعاوى تدخل في الاثنين."},{"id":"c5.table53-reading","ar":"تقرأ Table 5.3 غلط","explain":"Table 5.3 فيه median weekly earnings للرجال والنساء ونسبة أجر المرأة من أجر الرجل لكل مهنة: أعلى نسبة Service ‏84%، وأقل نسبة Natural resources, construction, and maintenance ‏71%. الغلط إنك تقرأ عمود Men بدال Women، أو تاخذ أعلى أجر بالدولار بدال أعلى نسبة، أو تفوّت إن الرجال يكسبون أكثر في كل المهن حتى sales and office.","fix":"افتح Table 5.3 في بلوك «Distributive Justice» بدرس ٢ واقرأ أسماء الأعمدة الثلاثة قبل الأرقام، وبعدين كرت C5S2-c-table-5-3.","sec":"MGT102-CH5-S2","coach":"افتح الجدول قدّامه واسأله: وين أعلى نسبة؟ وين أقل نسبة؟ وأي مهنة فيها أعلى أجر للنساء بالدولار؟ عشان يتعوّد يفرّق بين عمود النسبة وعمود الأجر."},{"id":"c5.perception-process","ar":"تغلط في خطوات الإدراك أو تحسبه موضوعي","explain":"Perception = select, organize, and interpret المدخلات الحسية (الحواس الخمس كلها) عشان تعطي meaning and order للعالم، وهو subjective مو objective determination. والعوامل اللي تخلّي مديرين يشوفون نفس الشي بشكل مختلف: personality, values, attitudes, moods، وكمان past experience and knowledge اللي تتنظّم في schemas.","fix":"ارجع لبلوكَي «Perception» و«Factors That Influence Managerial Perception and Schemas» في درس ٣، وبعدين كروت C5S3-c-perception وC5S3-c-perception-factors.","sec":"MGT102-CH5-S3","coach":"خلّه يقول الأفعال الثلاثة بالترتيب (select ← organize ← interpret) كم مرة بسرعة، وبعدين اسأله: الإدراك objective ولا subjective؟ وعدّد لي العوامل الأربعة."},{"id":"c5.schema-change","ar":"تحسب الـschemas ما تتغيّر أو كلها سيئة","explain":"Schemas are slow to change مو never change، وتحتاج considerable amount of contradictory information لأن الناس ينتبهون للمعلومات المتوافقة ويتجاهلون المخالفة فتتعزّز. والدقيقة منها functional تساعدك تفهم العالم، وغير الدقيقة dysfunctional.","fix":"ارجع لبلوك «Factors That Influence Managerial Perception and Schemas» في درس ٣ واقرأ الفخ، وبعدين كروت C5S3-c-schema وC5S3-c-functional-schema.","sec":"MGT102-CH5-S3","coach":"اسأله ثلاث صح وغلط شفهي: «schemas never change» / «people attend to inconsistent information» / «all schemas are harmful» — الثلاث غلط، وخلّه يصحّح كل وحدة بجملة."},{"id":"c5.gender-schema-stereotype","ar":"تقلب العلاقة بين gender schemas و stereotype","explain":"Gender schemas are a kind of stereotype، مو العكس؛ والـschema عموماً ممكن تكون دقيقة، أما stereotype فهي simplistic and often inaccurate ومبنية على صفة ظاهرة وحدة (age, gender, race). وفي قوائم gender schemas الـassertive وindependent للرجال، والـnurturing وexpressive للنساء.","fix":"ارجع لبلوك «Gender Schemas and Stereotypes» في درس ٣ واقرأ الفخ، وبعدين كروت C5S3-c-gender-schemas وC5S3-c-stereotype.","sec":"MGT102-CH5-S3","coach":"ارسم له دائرة كبيرة stereotype وداخلها دائرة gender schemas وخلّه يشرحها لك، وبعدين اسأله: assertive وnurturing كل وحدة لمين في الـgender schemas؟"},{"id":"c5.stereotype-vs-bias","ar":"تخلط بين stereotype و bias و implicit bias","explain":"Stereotype = اعتقاد simplistic عن الصفات المعتادة لفئة؛ bias = systematic tendency to use information about others بطريقة تطلّع inaccurate perceptions. وimplicit bias = attitudes or stereotypes تأثّر فيك in an unconscious manner، فلو السيناريو فيه «ما كان واعي» فهي implicit bias.","fix":"ارجع لبلوكَي «Gender Schemas and Stereotypes» و«Biases, Implicit Bias, Social Status, and Salience» في درس ٣، وبعدين كروت C5S3-c-stereotype وC5S3-c-bias وC5S3-c-implicit-bias.","sec":"MGT102-CH5-S3","coach":"اقرأ له تعريف واحد بالإنجليزي بدون الاسم وخلّه يقول المصطلح، وبعدين اسأله عن الكلمة المفتاحية في كل تعريف: belief / systematic tendency / unconscious."},{"id":"c5.status-vs-salience","ar":"تخلط بين social status و salience و similar-to-me","explain":"Social status effect = تشوف صاحب المكانة العالية أحسن بدون معلومة موضوعية؛ salience effect = تركّز على اللي conspicuously different عن المجموعة، ويتقيّم more extremely بالاتجاهين (مدح زايد ولوم زايد) مو سلبي بس. وsimilar-to-me = تشوف اللي يشبهك أحسن، زي المدراء البيض اللي يشوفون الرجال البيض أحسن.","fix":"ارجع لبلوك «Biases, Implicit Bias, Social Status, and Salience» في درس ٣ (مثال حفلة الشركة ومثال الموظف الهسباني الوحيد) واقرأ الفخ، وبعدين كروت C5S3-c-social-status وC5S3-c-salience-effect.","sec":"MGT102-CH5-S3","coach":"أعطه ثلاث مواقف: «مدير يمدح عضو الإدارة العليا بدون ما يعرفه» / «الموظف الوحيد المختلف ينمدح زيادة وينلام زيادة» / «مدير يرتاح للي من نفس خلفيته» وخلّه يسمّي كل أثر."},{"id":"c5.overt-vs-unintended","ar":"تخلط بين التمييز المتعمّد والظلم اللي بدون قصد","explain":"Inaccurate schemas وbiases تخلّي حتى المدير حسن النية يظلم unintentionally، أما overt discrimination فهو knowingly and willingly يعني متعمّد. وهو unethical and illegal مع بعض، وينتهك distributive وprocedural justice الاثنين.","fix":"ارجع لبلوك «Overt Discrimination» في درس ٣ واقرأ الفخ، وبعدين كرت C5S3-c-overt-discrimination.","sec":"MGT102-CH5-S3","coach":"في كل موقف اسأله سؤال واحد: «كان عارف إنه يظلم؟» لو إيه فهو overt، ولو لا فهو bias أو schema؛ وبعدين خلّه يقول كم مبدأ عدالة ينتهكه الـovert."},{"id":"c5.steps-count","ar":"تغلط في عدد خطوات Table 5.4 أو أولها","explain":"خطوات إدارة التنوّع ١١ — مو ١٠ (أدوار Table 5.2) ولا ١٢ (قطع Figure 5.1) — وأولها secure top management commitment. وما فيها حصص توظيف (quotas)، والعملية ongoing تحتاج frequent monitoring مو برنامج مرة وحدة.","fix":"ارجع لبلوك «Steps in Managing Diversity Effectively» في درس ٤ وسمّع Table 5.4 بالترتيب، وبعدين كرت C5S4-c-eleven-steps.","sec":"MGT102-CH5-S4","coach":"خلّه يعدّ الخطوات الـ١١ على أصابعه بالإنجليزي، وبعدين اسأله فجأة: كم دور في Table 5.2؟ كم قطعة في Figure 5.1؟ عشان ما تختلط الأعداد عنده."},{"id":"c5.awareness-vs-skills","ar":"تخلط بين diversity awareness و diversity skills والمرونة","explain":"Awareness = تعرف attitudes, biases, stereotypes حقّتك وتفهم منظور غيرك؛ skills = تتواصل وتتعامل فعلياً مع المختلفين (communication styles، nonverbal signals، حل سوء الفهم). وflexibility = تنفتح على طرق مختلفة بدون ما تحس بتهديد، مو إنك suppress your personal style.","fix":"ارجع لبلوك «Diversity Awareness, Diversity Skills, and Flexibility» في درس ٤ واقرأ الفخ، وبعدين كروت C5S4-c-diversity-awareness وC5S4-c-diversity-skills وC5S4-c-flexibility.","sec":"MGT102-CH5-S4","coach":"اقرأ له مواقف قصيرة («دورة عن لغة الجسد بين الثقافات» / «ورشة تكشف تحيّزك» / «تسمح لموظف يختصر الغدا ويطلع بدري») وخلّه يقول awareness ولا skills ولا flexibility."},{"id":"c5.step-example-mix","ar":"تربط المثال بخطوة غلط من الخطوات","explain":"تحط المثال تحت خطوة ثانية: cafeteria-style benefits وflexible hours = encourage flexibility، ربط رواتب المدراء بأهداف التنوّع (Coca-Cola) = reward، objective performance indicators = pay close attention to evaluation. وتطالع توزيع الفئات على المناصب = consider the numbers (مو quotas)، والشاهد اللي يعترض على التمييز = empower employees.","fix":"ارجع لبلوكَي «Evaluation, Numbers, Empowerment, and Rewards» و«Diversity Awareness, Diversity Skills, and Flexibility» في درس ٤، وبعدين كروت C5S4-c-evaluation-numbers وC5S4-c-empower-reward.","sec":"MGT102-CH5-S4","coach":"قل له المثال وهو يرد برقم الخطوة واسمها من Table 5.4؛ ولو قال consider the numbers يعني نفرض حصص، صحّحه: نطالع الأرقام ونفهم ليش."},{"id":"c5.mentor-vs-protege","ar":"تعكس mentor و protégé أو تحصر الإرشاد بالنصايح","explain":"Mentoring = experienced member (الـmentor) يعطي advice and guidance لـless experienced member (الـprotégé) ويساعده يتقدّم في المنظمة ومساره. والإرشاد الفعّال حسب David Thomas مو بس تعليمات وخبرة تقنية، العلاقة القريبة الداعمة equally important.","fix":"ارجع لبلوك «Multipronged Training and Mentoring» في درس ٤ واقرأ EXAM BOX والفخ، وبعدين كرت C5S4-c-mentoring.","sec":"MGT102-CH5-S4","coach":"اسأله: «مين ياخذ النصيحة، الـmentor ولا الـprotégé؟» وبعدين: «لو المرشد علّمه مهارات تقنية بس، هذا إرشاد فعّال كامل؟» لازم يذكر العلاقة الداعمة."},{"id":"c5.quid-vs-hostile","ar":"تخلط بين quid pro quo و hostile work environment","explain":"Quid pro quo = فيه مقايضة: sexual favors مقابل وظيفة أو ترقية أو زيادة أو تجنّب demotion or dismissal، وهو الأكثر تطرّفاً. Hostile work environment = جو intimidating, hostile, or offensive (نكت، صور، تعليقات على المظهر) بدون مقابل، وهو الأخفى.","fix":"ارجع لبلوك «Sexual Harassment» في درس ٤ واقرأ الفخ، وبعدين كرت C5S4-c-two-forms-harassment.","sec":"MGT102-CH5-S4","coach":"علّمه يسأل نفسه في كل موقف: «فيه مقابل وظيفي؟» لو إيه فهو quid pro quo، ولو لا وفيه جو مهين فهو hostile work environment؛ جرّب معه موقفين أو ثلاثة."},{"id":"c5.harassment-steps","ar":"تغلط في خطوات القضاء على التحرّش","explain":"الخطوات أربع: policy endorsed by top management، fair complaint procedure، corrective action as soon as possible، وeducation and training لكل الأعضاء including managers. والشكاوى يديرها neutral third party وتحمي الضحية والمتّهم الاثنين، والفصل للحالات الشديدة بس مو لكل حالة.","fix":"ارجع لبلوك «Sexual Harassment» في درس ٤ وفرّق بين القوائم الثلاث اللي كل وحدة فيها أربع، وبعدين كرت C5S4-c-eradicate-steps.","sec":"MGT102-CH5-S4","coach":"خلّه يعدّ الخطوات الأربع بالترتيب، وبعدين اسأله: مين يدير الشكوى؟ المتّهم ينعامل بعدل ولا لا؟ الفصل دايم ولا حسب الشدّة؟"}],"cases":[{"id":"C5-A","title":"Bahr Logistics: One Woman on the Dispatch Team","text":"Khalid manages the dispatch team at Bahr Logistics, a trucking company in Jeddah. His team has seven dispatchers: six men and Reem, the first woman ever hired into dispatch. Khalid has noticed something about himself. In meetings, his eyes keep going to Reem. When her new route plan saved fuel, he praised her in front of the whole company. When she was one day late with a report, he criticised her more harshly than he had ever criticised the men for the same mistake.\n\nIn March, Khalid learned that a senior dispatcher was refusing to share the route software with Reem while sharing it with every man on the team. Khalid stopped this the same day and gave her full access.\n\nAt the end of the year, Khalid decided the pay raises. He reviewed each dispatcher's delivery records carefully, allowed for the fact that two dispatchers had worked for three months with broken GPS units, and ignored their age and ethnicity. Fahad, who handled far more deliveries than anyone else with the fewest errors, received the largest raise. The others received smaller raises."},{"id":"C5-B","title":"Nakheel Hotels: Who Reaches the Top?","text":"Nakheel Hotels runs eight hotels across Saudi Arabia. Women are 45% of its staff and often earn top performance ratings, yet no woman has ever become a general manager. No written rule keeps women out, and none of the executives means to hold women back; they believe they promote only on merit.\n\nHR director Mona Al-Harbi decided to look closer. She counted how many women and men held each level of job in every hotel. Women filled 40% of department-head jobs but none of the 12 top executive posts. Mona then paired each new female department head with an experienced general manager. He meets her every month, advises her on how to advance, introduces her to useful contacts, and builds a close, supportive relationship with her.\n\nThat year, two complaints reached HR. At the Jeddah hotel, a receptionist reported that her supervisor said she would get the shift-leader promotion only if she accepted his sexual advances. At the Abha hotel, housekeepers reported that a group of maintenance workers kept telling sexual jokes and making sexual remarks about their appearance. The housekeepers now dread coming to work and find it hard to do their jobs."}],"questions":[{"n":101,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"term","topic":"diversity-definition","stem":"Which textbook term refers to the differences among people due to age, gender, religion, education, physical appearance, and any other characteristic people use to tell one another apart?","options":["Ethnicity","Diversity","Socioeconomic background","Cultural agility"],"answer":1,"why":"التعريف يعدّ كل الفروقات بين الناس (العمر، الجنس، الدين، التعليم، المظهر…) ويختم بـ any other characteristic، وهذا تعريف diversity بالحرف. القائمة مفتوحة، يعني هو المصطلح الشامل مو مصدر واحد منها.","wrong":[{"i":0,"mis":"c5.diversity-sources","note":"اخترتها لأن الإثنية نوع من الفروقات، بس هي مصدر واحد بس (أصل وطني، لغة، ثقافة) مو كل الفروقات."},{"i":2,"mis":"c5.diversity-sources","note":"الخلفية الاجتماعية-الاقتصادية وحدة من عناصر القائمة (طبقة + دخل)، مو التعريف كله."},{"i":3,"mis":"gen.neighbor","note":"تشبه الموضوع لأنها عن الثقافات، بس هي المرونة اللي يكسبها اللي يتنقّل بين ثقافتين أو أكثر، ميزة في الشغل مو تعريف للفروقات."}],"tests":["diversity","ethnicity","socioeconomic background","cultural agility"]},{"n":102,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"term","topic":"ethnicity-definition-and-census","stem":"According to the textbook, what does ethnicity mean in general, and how does the U.S. Census Bureau treat it?","options":["General: a shared national origin, language, or culture. Census: Hispanic or Latino, or not.","General: a shared national origin, language, or culture. Census: the six race categories.","General: a mix of social class and income factors. Census: Hispanic or Latino, or not.","General: seeing oneself as two or more races. Census: the six race categories."],"answer":0,"why":"الكتاب يعرّف ethnicity بشكل عام إنها تجميع الناس على صفة مشتركة زي national origin أو language أو culture، بس الـ U.S. Census Bureau يعامل الإثنية على سؤال واحد: الشخص Hispanic or Latino ولا Not Hispanic or Latino. أما الفئات الست (white, Asian…) فهذي race مو ethnicity.","wrong":[{"i":1,"mis":"c5.race-ethnicity-ses","note":"نص التعريف العام صح، بس الفئات الست حقّت race، والتعداد يعامل الإثنية بس Hispanic or Latino ولا لا."},{"i":2,"mis":"c5.race-ethnicity-ses","note":"نص التعداد صح، بس الطبقة والدخل تعريف socioeconomic background مو ethnicity."},{"i":3,"mis":"gen.neighbor","note":"النص الأول هو multiracial (تشوف نفسك من عرقين أو أكثر)، والفئات الست race، فالنصّين غلط."}],"tests":["ethnicity","race","socioeconomic background","multiracial"]},{"n":103,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"term","topic":"glass-ceiling","stem":"The textbook describes the glass ceiling as:","options":["a written company rule that limits how many women and minorities can be promoted to top jobs","the continuing gap between the median weekly earnings of women and those of men","unseen obstacles that stop women and minorities from rising to the most senior company jobs","the practice of keeping salaries secret, which weakens women's bargaining power on pay"],"answer":2,"why":"الـ glass ceiling استعارة (metaphor) لحواجز ما تنشاف تمنع النساء والأقليات من الترقية للمناصب العليا. المفتاح: ما ينشاف (invisible) + النساء والأقليات + أعلى المناصب.","wrong":[{"i":0,"mis":"c5.glass-ceiling","note":"اسمه زجاجي لأنه ما ينشاف ومو مكتوب في أي سياسة، والقاعدة المكتوبة شي واضح مو خفي."},{"i":1,"mis":"gen.neighbor","note":"هذي gender wage gap، الكتاب يحطها جنب الـ glass ceiling بس هي عن الأجر مو عن الترقية."},{"i":3,"mis":"gen.neighbor","note":"هذي pay secrecy، تضعف تفاوض النساء على الراتب وتأثّر على فجوة الأجور، مو على الوصول للقمة."}],"tests":["glass ceiling","gender wage gap","pay secrecy"]},{"n":104,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"term","topic":"eeoc-and-diversity-indexes","stem":"Which of the following pairs is correctly matched, according to the textbook?","options":["Corporate Equality Index: scores employers on their disability and inclusion policies","Rooney Rule: NFL internships for Black medical students from historically Black colleges","Catalyst: the federal agency that collects data on religious discrimination complaints","EEOC: declared in 2015 that job discrimination based on sexual orientation is illegal"],"answer":3,"why":"الـ EEOC هي اللي أعلنت في 2015 إن التمييز في الشغل بسبب sexual orientation غير قانوني حسب القانون الفيدرالي. باقي الأزواج كلها مبدّلة.","wrong":[{"i":0,"mis":"gen.neighbor","note":"هذا وصف Disability Equality Index، أما Corporate Equality Index فيقيّم الشركات على مساواة LGBTQ. الاسمين متشابهين وهذا الفخ."},{"i":1,"mis":"gen.neighbor","note":"الـ Rooney Rule تفرض مقابلة مرشّحَين اثنين على الأقل من الأقليات لوظيفة head coach، وتدريب طلاب الطب من HBCUs مبادرة ثانية."},{"i":2,"mis":"gen.neighbor","note":"Catalyst منظمة غير ربحية تسوّي أبحاث عن النساء في الأعمال، واللي جمعت بيانات شكاوى التمييز الديني (زادت أكثر من 50%) هي EEOC."}],"tests":["eeoc","sexual orientation","lgbtq","corporate equality index","disability equality index","rooney rule","hbcus","catalyst"]},{"n":105,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"concept","topic":"why-diversity-is-pressing","stem":"Which of the following is NOT one of the reasons the textbook gives for why diversity is a pressing concern for managers?","options":["There is a strong ethical imperative that minorities get equal opportunities, and unfair treatment is illegal.","Managing diversity well can improve effectiveness and help an organization gain a competitive advantage.","There is substantial evidence that diverse people still face unfair treatment from biases and stereotypes.","The glass ceiling has disappeared, so women and minorities now reach top jobs as easily as others."],"answer":3,"why":"الكتاب يقول الـ glass ceiling «beginning to crack»، يعني بدأ يتشقّق بس لسه فيه شغل كثير، مو اختفى. في نوفمبر 2022 كانت 32 امرأة بس من قادة Fortune 500 (6.4%).","wrong":[{"i":0,"mis":"gen.detail","note":"هذا السبب الأول بالضبط: واجب أخلاقي (ethical imperative)، وكمان المعاملة غير العادلة غير قانونية."},{"i":1,"mis":"gen.partial","note":"يمكن تذكّرت نص الفكرة بس (التنوّع لحاله ما يضمن أداء أعلى)، بس إدارته صح ترفع الفعالية وتجيب competitive advantage، وهذا سبب من الأسباب."},{"i":2,"mis":"gen.detail","note":"هذا السبب الثالث: فيه دليل كبير على استمرار الظلم بسبب biases و stereotypes و overt discrimination."}],"tests":["ethical imperative","competitive advantage","organizational effectiveness","glass ceiling"]},{"n":106,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"concept","topic":"civil-rights-1964-vs-1991","stem":"Table 5.1 lists two civil rights laws: Title VII of the Civil Rights Act and a later Civil Rights Act. Both prohibit discrimination. What does the later act add beyond Title VII?","options":["Protection for workers over the age of 40 and limits on mandatory retirement","Punitive and compensatory damages, on top of back pay, for intentional discrimination","Protection of the civilian jobs of military personnel called to active duty","A ban on discrimination in decisions about hiring, firing, pay, and promotion"],"answer":1,"why":"الـ Civil Rights Act (1991) يمنع التمييز زي Title VII، والإضافة الجديدة إنه يسمح بـ punitive and compensatory damages فوق الـ back pay في حالات التمييز المتعمّد. يعني الـ back pay كان موجود، والجديد هو التعويضات.","wrong":[{"i":0,"mis":"c5.eeo-law-coverage","note":"هذا وصف Age Discrimination in Employment Act (1967): حماية اللي فوق 40 وتقييد التقاعد الإجباري."},{"i":2,"mis":"c5.eeo-law-coverage","note":"هذا وصف قانون العسكريين Uniformed Services Employment and Reemployment Rights Act (1994)."},{"i":3,"mis":"gen.partial","note":"هذا موجود من أيام Title VII (يغطّي التوظيف والفصل والراتب والترقية)، وقانون 1991 يمنع التمييز زيّه بالضبط، فمو هو الإضافة."}],"tests":["title vii of the civil rights act","civil rights act of 1991","age discrimination in employment act","uniformed services employment and reemployment rights act"]},{"n":107,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"concept","topic":"cultural-agility-and-other-diversity","stem":"Which statement about diversity in the workforce is TRUE, according to the textbook?","options":["Physical appearance affects performance in most jobs, so it can fairly guide pay and promotion.","Only differences that the law protects, such as race and religion, can lead to unfair treatment.","Moving between two or more cultures gives many Hispanic Americans cultural agility, a work asset.","Differences in experience matter less today, because most teams draw members from one department."],"answer":2,"why":"الكتاب في مربّع Focus on DEI&B يقول كثير من الأمريكان اللاتينيين يتنقّلون بين ثقافتين أو أكثر، وهذا يعطيهم cultural agility، وهي ميزة (asset) في مكان الشغل. والخيارات الثانية كلها عكس كلام الكتاب عن other kinds of diversity.","wrong":[{"i":0,"mis":"gen.reversed","note":"الكتاب يقول العكس: المظهر ما له علاقة بالأداء، إلا في وظيفة يلعب فيها المظهر دور زي modeling."},{"i":1,"mis":"gen.absolute","note":"كلمة Only فخ: الكتاب يقول الأنواع الثانية من التنوّع (زي الخبرة والمظهر) كمان potential sources of unfair treatment."},{"i":3,"mis":"gen.reversed","note":"بالعكس، الكتاب يتكلّم عن انتشار (prevalence) الـ cross-functional teams اللي أعضاؤها من أقسام مختلفة، فالخبرات المتنوّعة مطلوبة."}],"tests":["cultural agility","other kinds of diversity","cross-functional teams","experience","physical appearance"]},{"n":108,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"scenario","topic":"diversity-beyond-hiring","stem":"A petrochemical company in Dammam set a goal to hire more women and employees from different nationalities, and it reached the goal in two years. However, these new employees are rarely asked for their ideas in meetings and are often left out of key projects. Based on the chapter, what is the company's main problem?","options":["It has hired diverse employees, but they are not yet treated as full members whose views count.","It has set its hiring targets too low, so it should now hire even more minority candidates.","It faces a glass ceiling, because a written company rule blocks these employees from top jobs.","It has a gender wage gap, because the new women employees earn less than the men do."],"answer":0,"why":"الشركة وظّفت ووصلت الرقم، بس الموظفين ما ينسمع لهم ولا يشاركون. الكتاب يقول إدارة التنوّع أكثر من التوظيف: لازم يكونون fully included and heard، not just recruited and hired.","wrong":[{"i":1,"mis":"c5.hiring-is-enough","note":"تحسب الحل توظيف أكثر، والشركة أصلاً وصلت هدفها. الكتاب يقول fully embracing diversity يحتاج أكثر من targets."},{"i":2,"mis":"c5.glass-ceiling","note":"ما فيه قاعدة مكتوبة في القصة، والـ glass ceiling أصلاً حاجز ما ينشاف ويخص الترقية للقمة."},{"i":3,"mis":"gen.keyword","note":"كلمة women في القصة تودّيك لفجوة الأجور، بس القصة ما ذكرت الرواتب أبداً."}],"tests":["effective management of diversity and inclusion","glass ceiling","gender wage gap"]},{"n":109,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"scenario","topic":"socioeconomic-background","stem":"Huda manages a chain of cafés in Madinah. Several of her baristas live on family incomes below the level the government uses to count a family as poor, and some struggle to pay for child care and housing. Huda adjusts their shifts around child-care needs and offers them training so they can advance and earn more. Which source of diversity is Huda mainly responding to?","options":["Ethnicity","Capabilities/disabilities","Socioeconomic background","Experience"],"answer":2,"why":"الفرق بين الموظفين هنا في الدخل والطبقة (دخل تحت الحد اللي تنحسب فيه العائلة فقيرة = poverty threshold، وصعوبة في رعاية الأطفال والسكن)، وهذا socioeconomic background = social class + income. والكتاب يقول المدير يكون sensitive and responsive ويعطيهم فرص يتعلّمون ويتقدّمون، بالضبط اللي سوّته هدى.","wrong":[{"i":0,"mis":"c5.race-ethnicity-ses","note":"ما فيه شي عن الأصل الوطني أو اللغة أو الثقافة، الفرق كله في الدخل."},{"i":1,"mis":"gen.keyword","note":"تعديل الشفتات يذكّرك بتسهيلات الإعاقة، بس ما فيه أي إعاقة في القصة."},{"i":3,"mis":"gen.keyword","note":"التدريب يخليك تفكّر في الخبرة، بس التدريب هو حل هدى مو الفرق اللي بين الموظفين. الفرق في الدخل."}],"tests":["socioeconomic background","poverty threshold","ethnicity","capabilities/disabilities","experience"]},{"n":110,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"scenario","topic":"pregnancy-discrimination-act","stem":"Laura works for a company in Texas. Soon after she tells her manager that she is pregnant, she is removed from the promotion list, even though her performance is the best on her team. According to Table 5.1, which law most directly prohibits this decision?","options":["Equal Pay Act","Pregnancy Discrimination Act","Family and Medical Leave Act","Americans with Disabilities Act"],"answer":1,"why":"قرار وظيفي (الترقية) انبنى على الحمل، و Pregnancy Discrimination Act (1978) يمنع التمييز ضد النساء في قرارات التوظيف بسبب pregnancy و childbirth.","wrong":[{"i":0,"mis":"c5.eeo-law-coverage","note":"هذا عن الأجر المتساوي للعمل المتساوي، والقصة عن ترقية مو راتب."},{"i":2,"mis":"c5.eeo-law-coverage","note":"الـ FMLA يعطي 12 أسبوع إجازة غير مدفوعة، ولورا ما طلبت إجازة، انحرمت من ترقية."},{"i":3,"mis":"c5.eeo-law-coverage","note":"الـ ADA يخص ذوي الإعاقة ويطلب accommodations، والقصة عن قرار ترقية بسبب الحمل، وللحمل قانون خاص في الجدول (1978)."}],"tests":["pregnancy discrimination act","equal pay act","family and medical leave act","americans with disabilities act"]},{"n":111,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"scenario","topic":"ada-accommodations","stem":"Khalid, a Saudi engineer working for a company in Houston, uses a wheelchair. He is fully qualified for his job, but the company refuses to add a ramp so he can reach the lab where his work is done. Which of the following requires the company to make this kind of change?","options":["Title VII of the Civil Rights Act","Americans with Disabilities Act","White House Guidelines on religious exercise","Family and Medical Leave Act"],"answer":1,"why":"خالد يحتاج تسهيل (accommodation) عشان يقدر يسوي شغله، واللي يلزم صاحب العمل بالتسهيلات لذوي الإعاقة هو Americans with Disabilities Act (1990): يمنع التمييز ويطلب reasonable accommodations.","wrong":[{"i":0,"mis":"gen.keyword","note":"كلمة Saudi تخليك تفكّر في national origin، بس المشكلة هنا الكرسي المتحرّك مو أصله."},{"i":2,"mis":"c5.eeo-law-coverage","note":"هي كمان تطلب reasonable accommodations، بس للممارسات الدينية زي الأعياد، وقصة خالد عن إعاقة مو دين."},{"i":3,"mis":"c5.eeo-law-coverage","note":"كلمة Medical تلخبطك، بس الـ FMLA يعطي 12 أسبوع إجازة غير مدفوعة، وما يلزم الشركة بأي تسهيلات زي المنحدر."}],"tests":["americans with disabilities act","reasonable accommodations","white house guidelines on religious exercise","title vii of the civil rights act","family and medical leave act"]},{"n":112,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"figure","topic":"figure-5-1-sources","stem":"Look at Figure 5.1, Sources of Diversity in the Workplace. Which of the following is NOT shown as a separate source in the figure?","img":"img/mgt102/figure-5-1.png","options":["Other characteristics","Experience","Job performance","Physical appearance"],"answer":2,"why":"الشكل فيه 12 شريحة: Age, Gender, Race, Ethnicity, Religion, Sexual orientation, Socioeconomic background, Capabilities/disabilities, Education, Experience, Physical appearance, Other characteristics. وما فيه شريحة اسمها Job performance.","wrong":[{"i":0,"mis":"c5.diversity-sources","note":"تبان حشو بس هي شريحة مستقلة في الشكل، وتقابل any other characteristic في التعريف."},{"i":1,"mis":"c5.diversity-sources","note":"Experience شريحة موجودة في الشكل، على اليسار جنب Education."},{"i":3,"mis":"c5.diversity-sources","note":"تحسبها غريبة على التنوّع، بس هي شريحة فعلاً في الشكل."}],"tests":["sources of diversity","figure 5.1","experience","physical appearance"]},{"n":113,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"figure","topic":"table-5-1-fmla","stem":"Look at Table 5.1. In which year was the Family and Medical Leave Act passed, and what does it require employers to provide?","img":"img/mgt102/table-5-1.png","options":["1991: 12 weeks of unpaid leave for medical and family reasons","1993: 12 weeks of paid leave for medical and family reasons","1993: 12 weeks of unpaid leave for medical and family reasons","1993: 12 weeks of unpaid leave for the employee's own illness only"],"answer":2,"why":"في الجدول سنة كل قانون مطبوعة تحت عند آخر سطر من وصفه، فسنة FMLA هي 1993 (و 1991 اللي فوقه حقّت Civil Rights Act). والوصف: 12 weeks of unpaid leave لأسباب طبية وعائلية، منها paternity ومرض أحد أفراد العائلة.","wrong":[{"i":0,"mis":"c5.eeo-law-year","note":"قريت السنة اللي فوق اسم القانون، و 1991 هي سنة Civil Rights Act."},{"i":1,"mis":"gen.detail","note":"الجدول يقول unpaid يعني غير مدفوعة، وهذا أشهر فخ في القانون."},{"i":3,"mis":"gen.partial","note":"الإجازة لأسباب طبية وعائلية، تشمل الأبوّة (paternity) ومرض أحد أفراد العائلة، مو بس مرض الموظف نفسه."}],"tests":["family and medical leave act","table 5.1","equal employment opportunity laws"]},{"n":114,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"list","topic":"title-vii-bases","stem":"Title VII of the Civil Rights Act prohibits discrimination in employment decisions on five bases. Which of the following is NOT one of them?","options":["Religion","National origin","Age","Color"],"answer":2,"why":"الأسس الخمسة لـ Title VII: race, religion, sex, color, national origin. العمر مو منهم، العمر يحميه Age Discrimination in Employment Act (1967) للي فوق 40.","wrong":[{"i":0,"mis":"gen.detail","note":"الدين من الخمسة، والكتاب يذكر Title VII بالاسم في جزء الدين."},{"i":1,"mis":"gen.detail","note":"الأصل الوطني (national origin) من الخمسة."},{"i":3,"mis":"gen.detail","note":"اللون من الخمسة، وناس تنساه لأنه قريب من race."}],"tests":["title vii of the civil rights act","age discrimination in employment act"]},{"n":115,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"list","topic":"eeo-law-order","stem":"Of the following equal employment opportunity laws in Table 5.1, which one was passed FIRST?","options":["Title VII of the Civil Rights Act","Age Discrimination in Employment Act","Equal Pay Act","Americans with Disabilities Act"],"answer":2,"why":"الترتيب في الجدول: 1963 Equal Pay Act، بعده 1964 Title VII، بعده 1967 ADEA، وبعدين 1990 ADA. فأولهم Equal Pay Act، قبل Title VII بسنة وحدة.","wrong":[{"i":0,"mis":"c5.eeo-law-year","note":"Title VII سنة 1964، بعد Equal Pay Act بسنة، وكثير يعكسونهم."},{"i":1,"mis":"c5.eeo-law-year","note":"قانون العمر سنة 1967، بعد الاثنين."},{"i":3,"mis":"c5.eeo-law-year","note":"الـ ADA سنة 1990، من آخر القوانين في الجدول."}],"tests":["equal pay act","title vii of the civil rights act","age discrimination in employment act","americans with disabilities act"]},{"n":116,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"tf","topic":"minority-group-trend","stem":"According to U.S. Census Bureau figures in the textbook, about one in three U.S. residents belongs to a minority group, and this share is projected to grow to close to 56% by 2060.","options":["True","False"],"answer":0,"why":"صح. حسب الـ U.S. Census Bureau تقريباً واحد من كل ثلاثة سكان في أمريكا ينتمي لـ minority group (يعني مو non-Hispanic white)، والمتوقّع في 2060 الأقليات يوصلون قرابة 56% من السكان.","wrong":[{"i":1,"mis":"gen.detail","note":"يمكن ما ثبت عندك الرقمين: واحد من كل ثلاثة اليوم، وقرابة 56% في 2060، يعني النسبة تكبر."}],"tests":["minority group"]},{"n":117,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"vocab","topic":"vocab-vigilant","stem":"In the sentence \"Managers need to be vigilant to ensure that employees are not discriminated against because of age,\" the word vigilant most nearly means:","options":["Strict and demanding","Watchful and alert","Calm and patient","Fair and generous"],"answer":1,"why":"vigilant = متيقّظ وعينه مفتوحة. المدير يراقب عشان ما يصير تمييز بسبب العمر.","wrong":[{"i":0,"mis":"gen.vocab","note":"الصرامة شي ثاني، vigilant عن الانتباه والمراقبة مو القسوة."},{"i":2,"mis":"gen.vocab","note":"الهدوء والصبر ما لهم علاقة بالكلمة."},{"i":3,"mis":"gen.vocab","note":"العدل هو هدف الجملة، بس الكلمة نفسها معناها منتبه."}],"tests":["vigilant"]},{"n":118,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"vocab","topic":"vocab-inadvertently","stem":"In the sentence \"Sometimes well-intentioned managers inadvertently treat various groups of employees differently,\" the word inadvertently most nearly means:","options":["Deliberately and on purpose","Openly and in public","Without meaning to","Only very rarely"],"answer":2,"why":"inadvertently = بدون قصد. والقرينة well-intentioned: المدير نيّته زينة، فالتفرقة تصير وهو ما يدري.","wrong":[{"i":0,"mis":"gen.vocab","note":"عكس المعنى تماماً، والجملة تقول المدير نيّته طيّبة."},{"i":1,"mis":"gen.vocab","note":"ما لها علاقة بالعلن أو السر."},{"i":3,"mis":"gen.vocab","note":"التكرار جاي من Sometimes، مو من inadvertently."}],"tests":["inadvertently"]},{"n":119,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"vocab","topic":"vocab-threshold","stem":"What does the word \"threshold\" mean?","options":["متوسّط / معدّل","عتبة / حدّ","مساعدة / دعم مالي","ضريبة / رسوم"],"answer":1,"why":"threshold = العتبة أو الحد اللي لو نزلت تحته تتغيّر حالتك، زي خط الفقر: العائلة اللي دخلها تحت الـ threshold تنحسب فقيرة.","wrong":[{"i":0,"mis":"gen.vocab","note":"المتوسط بالإنجليزي average أو median، مو threshold."},{"i":2,"mis":"gen.vocab","note":"المساعدة اسمها assistance أو benefits، وتجي في نفس الفقرة فتلخبطك."},{"i":3,"mis":"gen.vocab","note":"الضريبة tax، وجات جنبها child tax credits بس مو نفس الكلمة."}],"tests":["threshold"]},{"n":120,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"vocab","topic":"vocab-mandatory","stem":"What does the word \"mandatory\" mean?","options":["اختياري / حسب الرغبة","مبكّر / قبل وقته","إجباري / لازم","مدفوع / بأجر"],"answer":2,"why":"mandatory = إجباري، لازم غصب عنك. وتجي في وصف ADEA: restricts mandatory retirement يعني يقيّد التقاعد الإجباري.","wrong":[{"i":0,"mis":"gen.vocab","note":"هذا العكس تماماً، اختياري = optional."},{"i":1,"mis":"gen.vocab","note":"تربطها بالتقاعد فتحسبها early retirement، بس مبكّر = early."},{"i":3,"mis":"gen.vocab","note":"مدفوع = paid، وتجي في قانون الإجازة (unpaid) مو هنا."}],"tests":["mandatory"]},{"n":201,"lo":"LO5-3","sec":"MGT102-CH5-S2","type":"term","topic":"distributive-justice-definition","stem":"According to the textbook, distributive justice is a moral principle calling for:","options":["the use of clear, consistent rules whenever decisions about pay and promotions are made","identical or similar pay, promotions, and other resources for every member of the organization","fair distribution of pay, promotions, and other resources based on meaningful contributions","fair distribution of pay, promotions, and other resources based on characteristics such as age"],"answer":2,"why":"العدالة التوزيعية (distributive justice) = توزيع عادل للأجر والترقيات والموارد حسب الـ meaningful contributions اللي قدّمها الشخص، مو حسب صفات ما يتحكّم فيها. الكلمتين اللي تفضحها: fair distribution + contributions.","wrong":[{"i":0,"mis":"c5.distributive-vs-procedural","note":"القواعد والإجراءات أقرب لـ procedural justice، يعني عن طريقة اتخاذ القرار، مو التوزيع نفسه حسب المساهمات."},{"i":1,"mis":"c5.distributive-equal-outcomes","note":"شكله عادل بس الكتاب يقول صراحة إنها ما تعني إن الكل ياخذ نفس الشي (identical or similar outcomes)."},{"i":3,"mis":"gen.reversed","note":"قلبت القاعدة: العمر من الصفات اللي ما يتحكّم فيها الشخص، والكتاب يقول التوزيع ما يكون على أساسها."}],"tests":["distributive justice","meaningful contributions","irrelevant personal characteristics"]},{"n":202,"lo":"LO5-3","sec":"MGT102-CH5-S2","type":"term","topic":"procedural-justice-definition","stem":"Which moral principle focuses on making the decision process itself fair when managers decide who gets a raise or a promotion, or whom to lay off when the organization downsizes?","options":["Distributive justice","Procedural justice","The justice rule","The moral rights rule"],"answer":1,"why":"procedural justice عن عدالة الطريقة نفسها (fair procedures)، والكتاب يقول تنطبق على إجراءات زي تقييم الأداء، مين ياخذ زيادة أو ترقية، ومين ينفصل لما المنظمة تضطر تتقلّص (downsize). الفخ إن الزيادة والترقية نتائج، بس السؤال عن عدالة العملية مو النتيجة.","wrong":[{"i":0,"mis":"c5.distributive-vs-procedural","note":"كلمة raise و promotion تسحبك لها لأنها نتائج، بس distributive عن مين ياخذ وش حسب المساهمات، والسؤال عن عدالة طريقة القرار."},{"i":2,"mis":"gen.neighbor","note":"هذي قاعدة من الفصل 4 (قواعد القرار الأخلاقي)، مو واحد من مبدأي الفصل 5 لإدارة التنوّع."},{"i":3,"mis":"gen.neighbor","note":"قاعدة الحقوق الأخلاقية من الفصل 4 تحمي حقوق الناس الأساسية، مو عن عدالة طريقة القرار في إدارة التنوّع."}],"tests":["procedural justice","distributive justice","typical procedures","downsizing"]},{"n":203,"lo":"LO5-2","sec":"MGT102-CH5-S2","type":"term","topic":"spokesperson-role","stem":"Which managerial role involves backing diversity initiatives in the wider community and reaching out to diverse groups to interest them in career opportunities?","options":["Disseminator","Liaison","Spokesperson","Figurehead"],"answer":2,"why":"Spokesperson يتكلّم باسم المنظمة برّا: يدعم مبادرات التنوّع في المجتمع الأوسع (wider community) ويكلّم الفئات المتنوّعة عن فرص العمل. المفتاح إن الاتجاه للخارج، للمجتمع والمتقدّمين.","wrong":[{"i":0,"mis":"c5.role-duty-mix","note":"Disseminator كمان informational، بس يعلّم الموظفين داخل المنظمة بسياسات التنوّع، مو المجتمع برّا."},{"i":1,"mis":"c5.role-duty-mix","note":"Liaison يخلّي الأفراد المتنوّعين ينسّقون ويتعاونون مع بعض، مو يعرض فرص العمل على المجتمع."},{"i":3,"mis":"c5.role-duty-mix","note":"Figurehead يوصّل بشكل رمزي إن التنوّع هدف مهم، بس ما يروح للفئات المتنوّعة يعرض عليهم وظايف."}],"tests":["spokesperson","disseminator","liaison","figurehead","informational roles"]},{"n":204,"lo":"LO5-2","sec":"MGT102-CH5-S2","type":"term","topic":"social-influence","stem":"Managers usually carry more weight than rank-and-file employees, so when they commit to diversity, their power and status lead others to make a similar commitment. Research on ______ supports this link: people are likely to be persuaded by others who have high status.","options":["social influence","formal authority","the salience effect","implicit bias"],"answer":0,"why":"الكتاب يقول Research on social influence يدعم هالربط: الناس يتأثّرون ويقتنعون بأصحاب المكانة العالية (high status). أما formal authority فهي السبب اللي يخلّي تأثير المدير أكبر من rank-and-file، مو اسم البحث.","wrong":[{"i":1,"mis":"gen.neighbor","note":"formal authority موجودة في نفس الفقرة كسبب لتأثير المدير، بس البحث اللي يدعم الربط اسمه social influence."},{"i":2,"mis":"gen.neighbor","note":"salience effect من الدرس 3: تركّز انتباهك على اللي يختلف بشكل واضح عن المجموعة، ما له دخل بالإقناع."},{"i":3,"mis":"gen.neighbor","note":"implicit bias = اتجاهات أو صور نمطية تأثّر علينا بدون وعي، مو عن تأثّر الناس بأصحاب المكانة."}],"tests":["social influence","formal authority","rank-and-file employees"]},{"n":205,"lo":"LO5-2","sec":"MGT102-CH5-S2","type":"concept","topic":"managers-central-role","stem":"Which statement about the manager's central role in managing diversity is TRUE according to the textbook?","options":["Mainly the decisional roles affect diversity, because those roles control the organization's resources.","In every one of their managerial roles, managers can either advance diversity management or derail it.","Research on unconscious biases matters little, because unfair treatment of diverse groups is easy to see.","A more diverse environment makes it less challenging for managers to manage a diverse workforce."],"answer":1,"why":"الكتاب يقول in each of their managerial roles المدير إما promote أو derail إدارة التنوّع، وعشان كذا هو critical. يعني الأدوار العشرة كلها، مو بعضها.","wrong":[{"i":0,"mis":"c5.role-type-count","note":"كلمة resources تخلّيك تحسب الأدوار القرارية هي الأهم، والكتاب يقول كل دور حتى interpersonal و informational."},{"i":2,"mis":"c5.overt-vs-unintended","note":"بالعكس، الكتاب يقول البحث في unconscious biases حيوي لأن الظلم يصير بطرق خفيّة (subtle) مع الوقت، مو واضح."},{"i":3,"mis":"gen.reversed","note":"قلبتها: الكتاب يقول تنوّع البيئة يزيد تنوّع القوى العاملة ويزيد التحدّيات على المدير، مو يقلّلها."}],"tests":["critical managerial roles","effective management of diversity","decisional roles","unconscious biases","diversity challenges"]},{"n":206,"lo":"LO5-3","sec":"MGT102-CH5-S2","type":"concept","topic":"costly-lawsuits","stem":"Which statement about lawsuits over unfair treatment, such as the class-action suit Coca-Cola settled in 2000 for $192 million, is TRUE according to the textbook?","options":["Later, a sense of complacency led Coca-Cola to scale back its recruiting of Black executives.","Avoiding such lawsuits matters mainly for business reasons rather than for ethical ones.","Treating employees fairly is an ethical duty for managers, while the law usually treats it as optional.","The damage from such lawsuits goes beyond the money paid, since they can tarnish a company's image."],"answer":3,"why":"الكتاب يقول ضرر هالدعاوى أكبر من الفلوس اللي تندفع، لأنها tarnish a company's image (تشوّه سمعة الشركة). وتذكّر: تجنّبها مهم business و ethical مع بعض، والمدير عليه التزام أخلاقي وقانوني.","wrong":[{"i":0,"mis":"gen.reversed","note":"عكس القصة: الـ complacency عطّل تقدّمهم فضاعفوا جهودهم (redoubled)، وأعلنوا برنامج توظيف 10 سنوات للملوّنين وتدريب للقادة على التعرّف على التحيّز."},{"i":1,"mis":"c5.ethical-vs-business","note":"الكتاب يقول from both business and ethical perspectives، يعني الاثنين مع بعض مو التجاري أكثر."},{"i":2,"mis":"gen.partial","note":"أخذت نص الفكرة بس: في دول كثيرة المدير عليه التزام قانوني كمان، وإلا ترتفع عليه دعاوى زي أكثر من 30 موظفة في Ford."}],"tests":["costly lawsuits","class-action suit","coca-cola","sense of complacency","legal obligation"]},{"n":207,"lo":"LO5-3","sec":"MGT102-CH5-S2","type":"concept","topic":"ethical-vs-business-imperative","stem":"Which of the following belongs to the ETHICAL imperative for managing diversity, rather than to the reasons it makes good business sense?","options":["The variety of viewpoints that diverse employees bring can improve managerial decision making.","Replacing a valued employee who quits costs about twice their salary, plus the knowledge that is lost.","Two moral principles, distributive and procedural justice, call for fair treatment of members.","Employees from diverse backgrounds tend to be attuned to what diverse market segments want."],"answer":2,"why":"الواجب الأخلاقي (ethical imperative) يقوم على مبدأين أخلاقيين: distributive justice و procedural justice. الباقي كلها أسباب business: قرارات أحسن، توفير تكلفة البديل والمعرفة اللي تضيع، وفهم العملاء المتنوّعين.","wrong":[{"i":0,"mis":"c5.ethical-vs-business","note":"تنوّع وجهات النظر يحسّن القرار ويعطي competitive advantage، وهذا من الأسباب التجارية مو الأخلاقية."},{"i":1,"mis":"c5.ethical-vs-business","note":"ضعف الراتب والمعرفة اللي تضيع هي تكاليف الـ turnover، يعني سبب تجاري يخص الربحية."},{"i":3,"mis":"c5.ethical-vs-business","note":"الموظف المتنوّع attuned (فاهم) لوش يبي العملاء المتنوّعين، زي شركات السيارات اللي تحط نساء في فرق التصميم؛ هذا سبب تجاري."}],"tests":["ethical imperative","business imperative","competitive advantage","retention","turnover","indirect costs","diverse customers"]},{"n":208,"lo":"LO5-2","sec":"MGT102-CH5-S2","type":"scenario","topic":"entrepreneur-vs-resource-allocator","stem":"Fahad, CEO of a hospital group in Riyadh, commits a budget and a project team to develop a brand-new approach to managing diversity, one the group has never tried, aimed at removing bias and discrimination from its decisions. Which managerial role is Fahad performing?","options":["Entrepreneur","Resource allocator","Disturbance handler","Negotiator"],"answer":0,"why":"Entrepreneur = commits resources to develop new ways لإدارة التنوّع وإزالة التحيّز والتمييز. اللي يفضحها هنا brand-new approach، يعني ابتكار طريقة جديدة.","wrong":[{"i":1,"mis":"c5.entrepreneur-vs-allocator","note":"كلمة budget تسحبك لـ resource allocator، بس هو يوزّع موارد تدعم إدارة التنوّع؛ اللي يطوّر طريقة جديدة هو entrepreneur."},{"i":2,"mis":"c5.role-duty-mix","note":"Disturbance handler يتحرّك بسرعة يصلّح ظلم صار ويوقفه، وفهد هنا يبني طريقة جديدة مو يعالج مشكلة وقعت."},{"i":3,"mis":"c5.role-duty-mix","note":"Negotiator يشتغل مع جهات برّا زي الموردين والنقابات، وما فيه أي تفاوض في القصة."}],"tests":["entrepreneur","resource allocator","decisional roles"]},{"n":209,"lo":"LO5-2","sec":"MGT102-CH5-S2","type":"scenario","topic":"disturbance-handler-role","stem":"At a logistics firm in Jeddah, operations manager Noura finds out that a supervisor has been giving the worst night shifts only to the non-Saudi drivers. The same day, she fixes the schedule and orders the supervisor to stop. Which managerial role is Noura performing when she takes this action?","options":["Monitor","Leader","Disturbance handler","Negotiator"],"answer":2,"why":"Disturbance handler = takes quick action to correct inequalities and curtail discriminatory behavior. نورة تحرّكت بنفس اليوم، صلّحت الظلم ووقّفت التمييز، وهذا تعريفه بالضبط.","wrong":[{"i":0,"mis":"c5.role-duty-mix","note":"Monitor يقيّم قد إيش المعاملة عادلة، بس نورة ما وقفت عند التقييم، تحرّكت وصلّحت بسرعة."},{"i":1,"mis":"c5.role-duty-mix","note":"Leader يكون قدوة ويحط سياسات وإجراءات عامة، ونورة هنا عالجت حالة وحدة صارت فوراً."},{"i":3,"mis":"c5.role-duty-mix","note":"Negotiator يتعامل مع منظمات وجماعات زي الموردين والنقابات، مو مع مشرف داخل الشركة."}],"tests":["disturbance handler","monitor","leader","negotiator"]},{"n":210,"lo":"LO5-3","sec":"MGT102-CH5-S2","type":"scenario","topic":"distributive-justice-unequal-outcomes","stem":"At a café chain in Madinah, the manager gives Reem a bigger bonus, a better job title, and the most interesting assignments, because her effort and sales this year were substantially higher than her coworkers'. The others get smaller bonuses, and gender and age play no part. Does this fit the principle of distributive justice?","options":["No, because distributive justice requires that all members receive identical or similar outcomes.","Yes, because members who make substantially higher contributions can receive more favorable outcomes.","No, because distributive justice covers pay only, so job titles and assignments must be shared equally.","Yes, because distributive justice is about the procedures used, not about what each member receives."],"answer":1,"why":"العدالة التوزيعية ما تعني الكل ياخذ نفس الشي؛ تعني اللي ياخذ أكثر لازم يكون قدّم مساهمات أعلى بشكل واضح (substantially higher contributions). ريم أخذت أكثر بسبب جهدها ومبيعاتها، مو جنسها أو عمرها.","wrong":[{"i":0,"mis":"c5.distributive-equal-outcomes","note":"هذا أشهر فخ: الكتاب يقول صراحة إنها does not mean identical or similar outcomes."},{"i":2,"mis":"gen.partial","note":"الكتاب يذكر job titles و interesting job assignments و office space من ضمن اللي يتوزّع، مو الأجر بس."},{"i":3,"mis":"c5.distributive-vs-procedural","note":"«نعم» صح بس السبب غلط: الإجراءات هي procedural justice، و distributive عن مين ياخذ وش."}],"tests":["distributive justice","meaningful contributions","irrelevant personal characteristics"]},{"n":211,"lo":"LO5-3","sec":"MGT102-CH5-S2","type":"scenario","topic":"procedural-justice-three-conditions","stem":"Before deciding on raises, Khalid, a plant manager in Jubail, carefully appraises each worker's performance. One worker's output fell because his machine broke down for two weeks, so Khalid takes this into account, and he ignores the workers' age and ethnic background. These three things Khalid does are the textbook's examples of:","options":["Distributive justice","Monitor role","Disturbance handler role","Procedural justice"],"answer":3,"why":"الكتاب يقول procedural justice موجودة لما المدير (1) يقيّم الأداء بعناية، (2) ياخذ في الحسبان العوائق البيئية اللي برّا سيطرة الموظف زي machine breakdowns، (3) يتجاهل العمر والإثنية. وزي distributive، هي لازمة للأخلاق وعشان تتجنّب costly lawsuits.","wrong":[{"i":0,"mis":"c5.distributive-vs-procedural","note":"القرار عن زيادات فتحسبها توزيعية، بس السؤال عن طريقة اتخاذ القرار (الإجراءات)، والتوزيعية عن النتيجة نفسها."},{"i":1,"mis":"c5.role-duty-mix","note":"Monitor يقيّم مدى عدالة معاملة الموظفين، مو يقيّم أداء كل عامل عشان الزيادة."},{"i":2,"mis":"c5.role-duty-mix","note":"Disturbance handler يصلّح ظلم صار ويوقف التمييز بسرعة، وخالد هنا يمشي على إجراءات عادلة من البداية."}],"tests":["procedural justice","environmental obstacles","irrelevant personal characteristics","costly lawsuits"]},{"n":212,"lo":"LO5-2","sec":"MGT102-CH5-S2","type":"figure","topic":"table-5-2-negotiator","stem":"Look at Table 5.2. Hana, director of a hospital in Dammam, works with the hospital's main suppliers and with a group that represents its nurses to win their support for the hospital's diversity efforts. According to the table, which type of role and specific role is Hana performing?","img":"img/mgt102/table-5-2.png","options":["Interpersonal role: Liaison","Informational role: Spokesperson","Decisional role: Negotiator","Decisional role: Resource allocator"],"answer":2,"why":"في الجدول Negotiator تحت Decisional، ومثاله يشتغل مع منظمات زي الموردين (suppliers) وجماعات زي النقابات (labor unions) عشان يدعمون إدارة التنوّع. وهناء بالضبط تشتغل مع الموردين ومع جماعة تمثّل الممرضات.","wrong":[{"i":0,"mis":"c5.role-duty-mix","note":"فكرة التعاون تسحبك لـ Liaison، بس مثاله يخلّي الأفراد المتنوّعين ينسّقون ويتعاونون مع بعض، مو إن المديرة نفسها تشتغل مع موردين وجماعات برّا."},{"i":1,"mis":"c5.role-duty-mix","note":"Spokesperson كمان يتعامل مع برّا، بس مثاله يدعم مبادرات التنوّع في المجتمع ويعرض فرص العمل، مو الشغل مع الموردين."},{"i":3,"mis":"c5.role-duty-mix","note":"نفس النوع Decisional ونفس عبارة support and encourage في الجدول، بس Resource allocator يوزّع موارد، مو يشتغل مع موردين وجماعات."}],"tests":["table 5.2","negotiator","decisional roles","liaison","spokesperson","resource allocator"]},{"n":213,"lo":"LO5-3","sec":"MGT102-CH5-S2","type":"figure","topic":"table-5-3-reading","stem":"Look at Table 5.3. In which occupation do women earn the LOWEST percentage of men's earnings?","img":"img/mgt102/table-5-3.png","options":["Management, professional, and related","Service","Natural resources, construction, and maintenance","Sales and office"],"answer":2,"why":"شوف العمود الأخير (Women's Earnings as a Percentage of Men's): أصغر رقم 71 عند Natural resources, construction, and maintenance، يعني أكبر فجوة بالنسبة.","wrong":[{"i":0,"mis":"c5.table53-reading","note":"فيها أكبر فرق بالدولار (1,726 مقابل 1,284) بس نسبتها 74%، والسؤال عن النسبة مو المبلغ."},{"i":1,"mis":"gen.reversed","note":"Service نسبتها 84%، وهذي أعلى نسبة يعني أصغر فجوة، عكس المطلوب."},{"i":3,"mis":"c5.table53-reading","note":"Sales and office مثال الكتاب لمهنة أغلبها نساء والرجال فيها يكسبون أكثر، بس نسبتها 74% مو الأقل."}],"tests":["table 5.3","gender wage gap"]},{"n":214,"lo":"LO5-2","sec":"MGT102-CH5-S2","type":"list","topic":"manager-commitment-results","stem":"According to the textbook, which of the following is NOT a result of managers committing to diversity?","options":["Their commitment legitimizes the diversity management efforts of other organizational members.","Resources are devoted to diversity efforts, and members feel those efforts are supported and valued.","Their confidence in diverse employees helps others reduce prejudice caused by ignorance or stereotypes.","Once managers commit to diversity, rewards for supporting diversity efforts become unnecessary."],"answer":3,"why":"الكتاب يقول top management commitment and rewards الاثنين مع بعض critical ingredients لنجاح مبادرات التنوّع، فالالتزام ما يغني عن المكافآت. الباقي كلها نتائج ذكرها الكتاب لالتزام المدير.","wrong":[{"i":0,"mis":"gen.vocab","note":"يمكن ما فهمت legitimizes (يعطي شرعية)، بس هذي أول نتيجة ذكرها الكتاب لالتزام المدير."},{"i":1,"mis":"gen.detail","note":"هذي نتيجة صحيحة: الموارد تنصرف على الجهود والكل يحس إن جهوده مدعومة ومقدّرة."},{"i":2,"mis":"gen.detail","note":"صحيحة كمان: لما الناس يشوفون المدير واثق في الموظفين المتنوّعين يقلّ عندهم الـ prejudice اللي جاي من الجهل أو الصور النمطية."}],"tests":["legitimizes","prejudice","top management commitment and rewards"]},{"n":215,"lo":"LO5-2","sec":"MGT102-CH5-S2","type":"list","topic":"two-factors-managers-central","stem":"Besides managers' formal authority, the textbook gives two other factors that explain why managers are so central to the effective management of diversity. Which pair is correct?","options":["Underrepresented groups often start at a slight disadvantage, and small unfair differences in treatment can grow into major disparities.","Underrepresented groups often start at a slight disadvantage, but small unfair differences in treatment tend to fade over time.","Managers must give fair outcomes under distributive justice, and they must also follow fair procedures under procedural justice in every decision.","Diverse employees can improve managerial decision making, and more and more organizations now insist that their suppliers support diversity."],"answer":0,"why":"العاملين: (1) الفئات اللي تمثيلها ناقص تبدأ بـ slight disadvantage، خصوصاً لما تكون numerical minority، و(2) الفروق الصغيرة في المعاملة تتراكم (accumulate) وتصير major disparities مع الوقت لو تجاهلناها.","wrong":[{"i":1,"mis":"c5.small-differences","note":"النص الأول صح بس الثاني عكس الكتاب: الفروق الصغيرة ما تختفي، تتراكم وتكبر لو تجاهلناها."},{"i":2,"mis":"gen.neighbor","note":"هذولي مبدأي الواجب الأخلاقي (LO5-3)، مو العاملين اللي يخلّون المدير محوري."},{"i":3,"mis":"gen.neighbor","note":"هذي أسباب تجارية من قسم good business sense، مو العاملين اللي يشرحون ليش المدير محوري."}],"tests":["underrepresented groups","slight disadvantage","numerical minority","slight differences accumulate","major disparities","suppliers"]},{"n":216,"lo":"LO5-3","sec":"MGT102-CH5-S2","type":"tf","topic":"distributive-justice-progress","stem":"According to the textbook, organizations today are about as far from the ideal of distributive justice as they were fifty years ago.","options":["True","False"],"answer":1,"why":"غلط. الكتاب يقول things are getting better: قبل 50 سنة كان التمييز الصريح (overt discrimination) شائع، واليوم المنظمات inching closer (تقرّب شوي شوي) من العدالة التوزيعية. بس لسّا أغلب المدراء يحتاجون proactive approach، والنساء يكسبن أقل في كل المهن (Table 5.3).","wrong":[{"i":0,"mis":"gen.detail","note":"يمكن فجوة الأجور في Table 5.3 خلّتك تحس ما تغيّر شي، بس الكتاب يقول الوضع تحسّن عن قبل 50 سنة ولسّا ما وصلنا."}],"tests":["distributive justice","overt discrimination","inching closer","proactive approach"]},{"n":217,"lo":"LO5-3","sec":"MGT102-CH5-S2","type":"vocab","topic":"vocab-underscore","stem":"In the sentence \"Although this example is simplistic, it underscores one way in which diversity can lead to a competitive advantage,\" the word underscores most nearly means:","options":["plays down","highlights","simplifies","depends on"],"answer":1,"why":"underscore أصلها تحط خط تحت الكلمة، يعني تأكّد على الفكرة وتبرزها. المثال مبسّط بس يبرز (highlights) طريقة من الطرق اللي يجيب فيها التنوّع competitive advantage.","wrong":[{"i":0,"mis":"gen.reversed","note":"كلمة under تخلّيك تحسها تقلّل من الشي، بس معناها العكس: تبرزه وتأكّد عليه."},{"i":2,"mis":"gen.keyword","note":"سحبتك كلمة simplistic اللي في نفس الجملة، بس المبسّط هو المثال، و underscore معناها يبرز."},{"i":3,"mis":"gen.vocab","note":"depends on يعني يعتمد على، ما لها علاقة بمعنى underscore."}],"tests":["underscore"]},{"n":218,"lo":"LO5-3","sec":"MGT102-CH5-S2","type":"vocab","topic":"vocab-dwindle","stem":"In the sentence \"Managers take into account obstacles such as lack of supplies, machine breakdowns, or dwindling customer demand for a product,\" the word dwindling most nearly means:","options":["slowly shrinking","suddenly rising","staying the same","hard to predict"],"answer":0,"why":"dwindle يعني يتناقص شوي شوي. هنا الطلب على المنتج يقلّ، وهذا عائق برّا سيطرة الموظف، عشان كذا يدخل في procedural justice.","wrong":[{"i":1,"mis":"gen.reversed","note":"suddenly rising عكسها تماماً، والطلب اللي يزيد ما يكون عائق للأداء أصلاً."},{"i":2,"mis":"gen.vocab","note":"staying the same يعني ثابت، و dwindling فيها نقص مستمر."},{"i":3,"mis":"gen.vocab","note":"hard to predict يعني صعب التوقّع، بس الكلمة عن النقص مو عن عدم التوقّع."}],"tests":["dwindle"]},{"n":219,"lo":"LO5-2","sec":"MGT102-CH5-S2","type":"vocab","topic":"vocab-disparity","stem":"What does the word disparity mean?","options":["تراكم","التزام / واجب","تشابه / تطابق","تفاوت / فجوة"],"answer":3,"why":"disparity = فرق كبير وغير عادل بين ناس وناس. زي جملة الكتاب: slight differences in treatment can accumulate and result in major disparities.","wrong":[{"i":0,"mis":"gen.vocab","note":"تراكم معناها accumulate، وهي في نفس الجملة مع disparities فتلخبط بينهم."},{"i":1,"mis":"gen.vocab","note":"التزام/واجب معناها obligation، كلمة ثانية من الدرس."},{"i":2,"mis":"gen.reversed","note":"تشابه عكس المعنى؛ disparity عن الفرق والفجوة مو التشابه."}],"tests":["disparity"]},{"n":220,"lo":"LO5-3","sec":"MGT102-CH5-S2","type":"vocab","topic":"vocab-complacency","stem":"What does the word complacency mean?","options":["الالتزام والجدّية في العمل","الرضا عن النفس والتراخي","الشكوى والاعتراض الرسمي","التعويض المالي للمتضرّرين"],"answer":1,"why":"complacency = تحس إن كل شي تمام وتوقف تتعب. Coca-Cola قالت إن تقدّمها في التنوّع تعطّل بسبب sense of complacency.","wrong":[{"i":0,"mis":"gen.reversed","note":"الالتزام والجدّية عكسها؛ الـ complacency إنك ترتخي وتوقف الجهد."},{"i":2,"mis":"gen.vocab","note":"الشكوى والاعتراض معناها complaint، تشبهها بالشكل بس معناها غير."},{"i":3,"mis":"gen.vocab","note":"التعويض المالي قريب من قصة الـ 192 مليون، بس مو معنى الكلمة."}],"tests":["complacency","sense of complacency"]},{"n":301,"lo":"LO5-4","sec":"MGT102-CH5-S3","type":"term","topic":"perception-definition","stem":"According to the text, perception is best defined as:","options":["The process of collecting, storing, and recalling information about people and events in memory","The process of selecting, organizing, and interpreting sensory input to give the world meaning","An objective judgment of a situation, free from the manager's own personal interpretation","A simplistic and often inaccurate belief about the typical traits of a particular group of people"],"answer":1,"why":"الإدراك عملية بثلاث أفعال بالترتيب: select → organize → interpret للمدخلات الحسية (اللي تشوفه وتسمعه وتلمسه وتشمّه وتذوقه) عشان تعطي العالم حولك معنى ونظام. والكتاب يقول قرارات المدير مبنية على إدراك subjective، مو تحديد موضوعي.","wrong":[{"i":0,"mis":"c5.perception-process","note":"الأفعال هنا collect, store, recall تشبه شغل الذاكرة والـ schema، بس أفعال الإدراك select, organize, interpret."},{"i":2,"mis":"c5.perception-process","note":"هذا اللي «أغلب الناس يظنونه» والكتاب يرفضه: تفسير المدير للموقف مجرد interpretation، يعني الإدراك subjective."},{"i":3,"mis":"gen.neighbor","note":"هذا تعريف stereotype، مصطلح من نفس القسم بس هو اعتقاد عن فئة من الناس مو عملية إدراك."}],"tests":["perception","subjective perceptions"]},{"n":302,"lo":"LO5-4","sec":"MGT102-CH5-S3","type":"term","topic":"schema-definition","stem":"Which term describes an abstract knowledge structure, stored in memory, that people use to organize and interpret information about a person, an event, or a situation?","options":["Stereotype","Perception","Schema","Bias"],"answer":2,"why":"الكلمات المفتاح: abstract knowledge structure + stored in memory + عن شخص أو حدث أو موقف = schema. هو القالب اللي في مخك تفسّر فيه أي شخص أو موقف جديد يشبهه.","wrong":[{"i":0,"mis":"gen.neighbor","note":"stereotype كمان فكرة في المخ، بس هو اعتقاد مبسّط وغالباً غلط عن فئة معيّنة، مو بنية معرفية عامة عن أي شخص أو حدث أو موقف."},{"i":1,"mis":"c5.perception-process","note":"الإدراك هو العملية نفسها (select, organize, interpret)، أما الشي المخزّن في الذاكرة اللي يوجّه العملية فهو الـ schema."},{"i":3,"mis":"gen.neighbor","note":"bias ميل منهجي في استخدام المعلومات عن الناس، مو بنية مخزّنة في الذاكرة."}],"tests":["schema"]},{"n":303,"lo":"LO5-4","sec":"MGT102-CH5-S3","type":"term","topic":"bias-definition","stem":"Which term refers to a systematic tendency to use information about other people in ways that lead to inaccurate perceptions?","options":["Stereotype","Bias","Schema","Perception"],"answer":1,"why":"الكلمات المفتاح: systematic tendency + تستخدم المعلومات عن الآخرين + توصّل لـ inaccurate perceptions = bias. وأخطر شي فيه إن الناس غالباً ما يدرون إن إدراكهم غلط.","wrong":[{"i":0,"mis":"c5.stereotype-vs-bias","note":"stereotype اعتقاد مبسّط عن خصائص فئة، أما bias فهو ميل منهجي في طريقة استخدامك للمعلومات."},{"i":2,"mis":"gen.neighbor","note":"schema بنية معرفية مخزّنة في الذاكرة، مو ميل منهجي يخرّب الإدراك."},{"i":3,"mis":"gen.keyword","note":"اخترته عشان كلمة perceptions في السؤال، بس الإدراك هو العملية نفسها، والميل اللي يخلّيها تطلع غلط هو bias."}],"tests":["bias","inaccurate perceptions"]},{"n":304,"lo":"LO5-4","sec":"MGT102-CH5-S3","type":"term","topic":"implicit-bias-definition","stem":"Some companies have a cross-functional interview team meet after each interview to discuss the candidate. The goal is to catch attitudes and stereotypes that can shape interviewers' decisions without them realizing it. What does the text call this problem?","options":["Implicit bias","Overt discrimination","Gender schemas","Stereotype"],"answer":0,"why":"العبارة المفتاح without realizing it يعني unconscious: الـ implicit bias هو attitudes or stereotypes تأثّر على فهمنا وأفعالنا وقراراتنا بدون وعي، ويشتغل involuntarily and without awareness. وعشان كذا بعض الشركات تحط cross-functional interview team يجتمع بعد المقابلة ويناقش المرشّح، عشان تحيّزات كل عضو تنكشف وتنفحص.","wrong":[{"i":1,"mis":"c5.overt-vs-unintended","note":"التمييز الصريح عكسه تماماً: knowingly and willingly يعني عن علم وقصد، مو بدون وعي."},{"i":2,"mis":"gen.neighbor","note":"gender schemas أفكار مسبقة عن الرجال والنساء بس، والمشكلة هنا أعم ومحورها إنها تصير بدون وعي."},{"i":3,"mis":"c5.stereotype-vs-bias","note":"اخترته لأن كلمة stereotypes في السؤال، بس الـ stereotype هو الاعتقاد نفسه، والمصطلح اللي يوصف تأثيره اللاواعي على قراراتنا هو implicit bias."}],"tests":["implicit bias","cross-functional interview team"]},{"n":305,"lo":"LO5-4","sec":"MGT102-CH5-S3","type":"concept","topic":"gender-schemas-definition","stem":"Which statement correctly describes gender schemas according to the text?","options":["They are simplistic beliefs about any group, and stereotypes are one kind of them.","They are accurate ideas about men and women, since research found them common.","They are preconceived ideas about men and women and one kind of stereotype.","They are ideas about men and women that people first learn at work, not in childhood."],"answer":2,"why":"الـ gender schemas هي أفكار مسبقة (preconceived notions) عن طبيعة الرجال والنساء وصفاتهم واتجاهاتهم وسلوكهم وتفضيلاتهم. والكتاب يقول Gender schemas are a kind of stereotype، يعني stereotype هو المظلّة الأوسع، وأي schema تربط صفات الشخص بصفة ظاهرة وحدة زي الجنس bound to be inaccurate.","wrong":[{"i":0,"mis":"c5.gender-schema-stereotype","note":"هذا تعريف stereotype (اعتقاد مبسّط عن أي فئة) والعلاقة مقلوبة كمان: الـ gender schemas خاصة بالرجال والنساء وهي نوع من stereotype، مو العكس."},{"i":1,"mis":"gen.keyword","note":"البحث قال إنها منتشرة (prevalent) بين الأمريكيين البيض من الطبقة المتوسطة، مو إنها صحيحة؛ والكتاب يقول إنها غلط أكيد."},{"i":3,"mis":"gen.detail","note":"الكتاب يقول ممكن تتعلّمها من الطفولة (البنت ممكن تنشجّع على ألعاب الشاحنات والأدوات، والولد غالباً ما ينشجّع على الدمى وأحياناً ينمنع منها) والمجتمع يعزّزها، مو إنها تبدأ في الشغل."}],"tests":["gender schemas","stereotype"]},{"n":306,"lo":"LO5-4","sec":"MGT102-CH5-S3","type":"concept","topic":"schemas-slow-to-change","stem":"Which statement about schemas is correct according to the text?","options":["They never change once formed, even after contradictory information appears.","They are slow to change and need a lot of contradictory information to change.","They are always dysfunctional, so managers should avoid using them at all.","They weaken over time because people focus on information that contradicts them."],"answer":1,"why":"الـ schemas مقاومة للتغيير لأننا ننتبه للمعلومات اللي توافقها ونطنّش اللي تخالفها، فتقوى مع الوقت. بس مو مستحيل تتغيّر: هي بطيئة التغيير وتحتاج كمية كبيرة من المعلومات المتناقضة (considerable amount of contradictory information).","wrong":[{"i":0,"mis":"c5.schema-change","note":"الكتاب يقول صراحة هذا ما يعني إنها ما تتغيّر أبداً؛ لو كذا ما كنا نتعلّم من أخطائنا، هي بس بطيئة."},{"i":2,"mis":"c5.schema-change","note":"مو كل الـ schemas سيئة: الدقيقة functional وتساعدنا نفهم العالم، وبدونها ما نقدر نفهم كمية المعلومات اللي نواجهها."},{"i":3,"mis":"gen.reversed","note":"قلبت الاتجاه: الناس ينتبهون للمعلومات اللي توافق الـ schema، فهي تقوى مع الوقت مو تضعف."}],"tests":["schema","functional schema","dysfunctional schema"]},{"n":307,"lo":"LO5-4","sec":"MGT102-CH5-S3","type":"concept","topic":"overt-vs-unintended","stem":"What is the key difference between overt discrimination and the unfair treatment that comes from inaccurate schemas and biases?","options":["Overt discrimination happens without awareness, while biases are deliberate choices.","Overt discrimination violates only procedural justice, while biases violate distributive justice.","Overt discrimination is intentional, while schemas and biases can cause unintended unfairness.","Overt discrimination is unethical but legal, while unfairness caused by biases is illegal."],"answer":2,"why":"الفرق الجوهري في القسم: الـ schemas الغلط والتحيّزات تخلّي حتى المدير حسن النيّة يظلم بدون قصد، أما overt discrimination فهو knowingly and willingly يعني متعمّد. وهو unethical و illegal مع بعض، وينتهك distributive و procedural justice الاثنين.","wrong":[{"i":0,"mis":"c5.overt-vs-unintended","note":"عكست الاثنين: اللي يشتغل بدون وعي هو التحيّز، والمتعمّد هو التمييز الصريح."},{"i":1,"mis":"c5.distributive-vs-procedural","note":"التمييز الصريح ينتهك المبدأين مع بعض (distributive و procedural)، مو واحد بس."},{"i":3,"mis":"gen.partial","note":"الكتاب يقول التمييز الصريح unethical و illegal الاثنين، مو غير أخلاقي بس."}],"tests":["overt discrimination","bias","inaccurate schemas","distributive justice","procedural justice"]},{"n":308,"lo":"LO5-4","sec":"MGT102-CH5-S3","type":"scenario","topic":"salience-effect","stem":"Noura is the only woman on a team of seven engineers at a logistics firm in Jeddah. In meetings, her manager watches her more closely than anyone else. When her project succeeds, he praises her far more than the others, and when she misses one deadline, he criticizes her much more harshly than he would criticize anyone else. This best illustrates:","options":["The social status effect","The similar-to-me effect","Overt discrimination","The salience effect"],"answer":3,"why":"نورة هي الوحيدة المختلفة في الفريق، فصارت محط الانتباه وتقييمها صار متطرّف في الاتجاهين: مدح زيادة لما تنجح ولوم زيادة لما تتأخر = salience effect. العلامة هي التقييم المتطرّف إيجاباً وسلباً.","wrong":[{"i":0,"mis":"c5.status-vs-salience","note":"ما فيه فرق مكانة أو منصب في القصة؛ هي بس مختلفة عن باقي الفريق."},{"i":1,"mis":"c5.status-vs-salience","note":"similar-to-me يعني تفضّل اللي يشبهك، والمدير هنا ما فضّلها، بالغ معها في المدح وفي اللوم."},{"i":2,"mis":"c5.overt-vs-unintended","note":"ما حرمها عن قصد من فرصة أو نتيجة؛ الانتباه الزايد هذا يصير غالباً inadvertently يعني بدون قصد."}],"tests":["salience effect","salience","implicit bias"]},{"n":309,"lo":"LO5-4","sec":"MGT102-CH5-S3","type":"scenario","topic":"social-status-scenario","stem":"At a company dinner in Riyadh, Fahad is introduced to two men of the same age. All he learns is that one sits on the top management team and the other supervises the mailroom. With no other information, Fahad assumes the executive is smarter, more capable, and more believable. Which idea from the text best explains Fahad's assumption?","options":["Salience: being conspicuously different from the other members of a group","Social status: a person's real or perceived position in society or at work","Similar-to-me effect: seeing people who are like ourselves more positively","Overt discrimination: knowingly denying people opportunities and outcomes"],"answer":1,"why":"فهد حكم على الاثنين من مكانتهم بس (إدارة عليا ضد مشرف غرفة البريد) بدون أي معلومات موضوعية. والـ social status هي مكانة الشخص الحقيقية أو المتصوَّرة (real or perceived) في المجتمع أو المنظمة، ومنها يجي الـ social status effect: تشوف صاحب المكانة العالية أذكى وأقدر وأصدق. وهذا مثال الكتاب نفسه في حفلة الشركة.","wrong":[{"i":0,"mis":"c5.status-vs-salience","note":"ما فيه أحد لافت أو مختلف عن مجموعة؛ الاثنين نفس العمر، والفرق الوحيد بينهم هو المكانة."},{"i":2,"mis":"c5.status-vs-salience","note":"القصة ما تقول إن واحد منهم يشبه فهد؛ الحكم مبني على المنصب العالي."},{"i":3,"mis":"c5.overt-vs-unintended","note":"فهد ما حرم أحد من فرصة عن قصد، هذا انطباع في إدراكه وبس."}],"tests":["social status","social status effect","implicit bias"]},{"n":310,"lo":"LO5-4","sec":"MGT102-CH5-S3","type":"scenario","topic":"stereotype-scenario","stem":"Majed, an IT manager at a tech company in Riyadh, rejects a highly qualified 55-year-old programmer. He explains that people of that age cannot keep up with new technology, although he never checked the applicant's actual skills. Majed's decision is most likely based on:","options":["A stereotype","The salience effect","The social status effect","A functional schema"],"answer":0,"why":"ماجد حكم على المبرمج من صفة فئته (العمر) وافترض إن كل اللي في هالعمر ما يواكبون التقنية = stereotype: اعتقاد مبسّط وغالباً غلط عن فئة، مبني على صفة ظاهرة زي العمر أو الجنس أو العرق.","wrong":[{"i":1,"mis":"c5.status-vs-salience","note":"salience عن الانتباه الزايد لشخص بارز داخل مجموعة، مو عن افتراض صفات فئة كاملة."},{"i":2,"mis":"c5.status-vs-salience","note":"social status عن المكانة والمنصب، والمبرمج انحكم عليه من عمره مو من مكانته."},{"i":3,"mis":"c5.schema-change","note":"الـ schema تكون functional لما تكون دقيقة، وهذي غلط وظلمت شخص مؤهّل، يعني dysfunctional."}],"tests":["stereotype","dysfunctional schema"]},{"n":311,"lo":"LO5-4","sec":"MGT102-CH5-S3","type":"scenario","topic":"similar-to-me-effect","stem":"Khalid, a 52-year-old regional manager at a bank in Dammam, must promote one of three candidates to branch manager. He picks Saleh, who is close to his age and shares his ethnic background, although the two younger candidates from other backgrounds have clearly stronger results. Khalid honestly believes Saleh is the best choice. Khalid's decision is best explained by:","options":["Overt discrimination","The salience effect","The similar-to-me effect","The social status effect"],"answer":2,"why":"خالد شاف صالح أحسن لأنه يشبهه (قريب من عمره ونفس خلفيته الإثنية) مو لأن أداءه أحسن = similar-to-me effect: الميل إننا نشوف اللي يشبهونا بشكل أحلى من اللي يختلفون عنا (التعريف في ملزمة الفصل). والكتاب نفسه يذكر هذا كثالث قرار سيئ من الإدراك غير الدقيق: ترقية مدير أداؤه ضعيف لأن عنده نفس الـ «diversity profile» حق اللي يقرّر. وبما إن خالد مقتنع إن قراره صح، فهذا إدراك منحاز بدون وعي، مو تمييز متعمّد.","wrong":[{"i":0,"mis":"c5.overt-vs-unintended","note":"overt discrimination = حرمان الناس من فرص بشكل متعمّد وعن علم. خالد مقتنع إن قراره صح وما يقصد يحرم أحد، فهذا إدراك منحاز مو تمييز صريح."},{"i":1,"mis":"c5.status-vs-salience","note":"salience effect = الشخص اللي لافت لأنه مختلف عن مجموعته (زي الوحيد من نوعه) ينلاحظ ويُقيَّم بشكل مبالغ. صالح مو مختلف ولا لافت، بالعكس هو يشبه مديره."},{"i":3,"mis":"c5.status-vs-salience","note":"social status effect = نشوف أصحاب المكانة الاجتماعية العالية أحسن. ما فيه فرق مكانة بين المرشّحين؛ خالد اختار صالح لأنه يشبهه."}],"tests":["similar-to-me effect","diversity profile","inaccurate perceptions"]},{"n":312,"lo":"LO5-4","sec":"MGT102-CH5-S3","type":"list","topic":"perception-factors","stem":"According to the text, several managers can perceive the same person or situation differently because they differ in four individual factors. Which of the following is NOT one of these factors?","options":["Personality","Intelligence","Moods","Values"],"answer":1,"why":"العوامل الأربعة اللي تخلّي إدراك المدراء يختلف (من الفصل 3): personality, values, attitudes, moods. الذكاء (intelligence) مو منها.","wrong":[{"i":0,"mis":"gen.detail","note":"الشخصية من الأربعة، ومثالها openness to experience: المنفتح يشوف المدراء الشباب فرصة تعلّم والمنغلق يشوفهم تهديد."},{"i":2,"mis":"gen.detail","note":"يمكن حسبت المزاج شي مؤقت ما يدخل، بس الكتاب حاطه من الأربعة."},{"i":3,"mis":"gen.detail","note":"القيم من الأربعة اللي يذكرها الكتاب مع الشخصية والاتجاهات والمزاج."}],"tests":["factors that influence managerial perception","personality","values","attitudes","moods"]},{"n":313,"lo":"LO5-4","sec":"MGT102-CH5-S3","type":"list","topic":"three-bad-decisions","stem":"According to the text, inaccurate perceptions can lead managers to make three bad decisions about diverse employees. Which of the following is NOT one of them?","options":["Not hiring people who are qualified for the job","Failing to promote top performers, who may then join competitors","Promoting weak managers who share the decision maker's diversity profile","Paying diverse employees less than others for doing the same work"],"answer":3,"why":"القرارات السيئة الثلاث في الكتاب: (1) ما توظّف المؤهّلين، (2) ما ترقّي أصحاب الأداء العالي فيروحون للمنافسين، (3) ترقّي مدراء أداؤهم ضعيف لأن عندهم نفس الـ diversity profile حق اللي يقرّر. الراتب الأقل على نفس الشغل ظلم أكيد، بس مو من هالقائمة.","wrong":[{"i":0,"mis":"gen.detail","note":"هذا أول قرار في القائمة: ما توظّف ناس مؤهّلين بسبب إدراك غلط عن عمرهم أو إثنيتهم."},{"i":1,"mis":"gen.detail","note":"هذا الثاني، والكتاب يضيف إن الموظف الممتاز ممكن ياخذ مهاراته للمنافسين."},{"i":2,"mis":"gen.detail","note":"يمكن حسبت الترقية شي إيجابي ما ينحسب قرار سيئ، بس هذا ثالث قرار: ترقية واحد ضعيف لأنه يشبه اللي يقرّر."}],"tests":["inaccurate perceptions","bad decisions concerning diversity","diversity profile"]},{"n":314,"lo":"LO5-4","sec":"MGT102-CH5-S3","type":"tf","topic":"avoiding-implicit-bias","stem":"According to the text, even though implicit bias works without awareness, managers can reduce it by recognizing it and by basing decisions such as promotions and pay raises on objective information about employees' performance.","options":["True","False"],"answer":0,"why":"صح. الكتاب يقول إن الوعي بهالتحيّز + الاعتماد على objective information عن قدرات الموظف وأداءه قد ما تقدر في قرارات المهام والزيادات والترقيات يساعد المدير يتجنّب implicit bias. وبعض الشركات كمان تستخدم cross-functional interview team عشان التحيّزات تنكشف.","wrong":[{"i":1,"mis":"gen.detail","note":"حسبت إن التحيّز اللي يشتغل بدون وعي ما له علاج، بس الكتاب يعطي حلّين: إنك تنتبه له وتعتمد على معلومات موضوعية عن الأداء."}],"tests":["implicit bias","objective information"]},{"n":315,"lo":"LO5-4","sec":"MGT102-CH5-S3","type":"vocab","topic":"vocab-chastise","stem":"In the sentence \"If he misses a deadline, he is excessively chastised,\" the word \"chastised\" most nearly means:","options":["Rewarded","Scolded","Excused","Ignored"],"answer":1,"why":"chastise = يوبّخ ويهزّئ. الجملة عن الموظف البارز اللي ينلام زيادة لما يفوّت الموعد، فالمعنى scolded.","wrong":[{"i":0,"mis":"gen.vocab","note":"هذا عكس المعنى؛ المكافأة ما تجي لما يفوّت الموعد."},{"i":2,"mis":"gen.vocab","note":"excused يعني سامحوه، بس excessively يعني بالغوا في الشي، والبروز يجيب لوم زيادة مو تسامح."},{"i":3,"mis":"gen.vocab","note":"الـ salience effect يعني انتباه زايد، فمستحيل يكون طنّشوه."}],"tests":["chastise"]},{"n":316,"lo":"LO5-4","sec":"MGT102-CH5-S3","type":"vocab","topic":"vocab-pervasive","stem":"In the sentence \"Research says implicit bias is pervasive in daily life, such as employment, education, and criminal justice,\" the word \"pervasive\" most nearly means:","options":["Rare","Temporary","Widespread","Harmless"],"answer":2,"why":"pervasive = منتشر في كل مكان تقريباً. الجملة تعدّد مجالات كثيرة (التوظيف، التعليم، العدالة الجنائية)، فالمعنى widespread.","wrong":[{"i":0,"mis":"gen.vocab","note":"rare عكس pervasive، والجملة تقول إنه موجود في مجالات كثيرة."},{"i":1,"mis":"gen.vocab","note":"الكلمة عن الانتشار في المجالات، مو عن قد إيش يطوّل."},{"i":3,"mis":"gen.vocab","note":"الكتاب يقول implicit bias يسبّب معاملة غير عادلة فهو مو harmless، و pervasive معناها الانتشار أصلاً."}],"tests":["pervasive"]},{"n":317,"lo":"LO5-4","sec":"MGT102-CH5-S3","type":"vocab","topic":"vocab-inadvertently","stem":"What does \"inadvertently\" mean?","options":["بشكل متعمّد","بشكل لافت","بشكل منتظم","بدون قصد"],"answer":3,"why":"inadvertently = بدون قصد، يعني سوّاها وهو ما انتبه ولا كان ناوي. زي المدير اللي inadvertently ينتبه للموظف المختلف أكثر بسبب الـ salience effect.","wrong":[{"i":0,"mis":"gen.vocab","note":"هذا معنى deliberate، عكس inadvertently تماماً."},{"i":1,"mis":"gen.vocab","note":"هذا معنى conspicuously، الكلمة اللي في تعريف الـ salience effect."},{"i":2,"mis":"gen.vocab","note":"هذا قريب من systematic اللي في تعريف bias، مو inadvertently."}],"tests":["inadvertently"]},{"n":318,"lo":"LO5-4","sec":"MGT102-CH5-S3","type":"vocab","topic":"vocab-preconceived","stem":"What does \"preconceived\" mean?","options":["مسبق","مبسّط زيادة","متناقض","منتشر"],"answer":0,"why":"preconceived = مسبق، فكرة حاطها في بالك من قبل لا تعرف الشي. ومنها تعريف gender schemas: preconceived notions عن الرجال والنساء.","wrong":[{"i":1,"mis":"gen.vocab","note":"هذا معنى simplistic اللي في تعريف stereotype."},{"i":2,"mis":"gen.vocab","note":"هذا معنى contradictory، زي المعلومات المتناقضة اللي تغيّر الـ schema."},{"i":3,"mis":"gen.vocab","note":"هذا معنى prevalent أو pervasive، مو preconceived."}],"tests":["preconceived"]},{"n":401,"lo":"LO5-5","sec":"MGT102-CH5-S4","type":"term","topic":"mentoring-definition","stem":"A process in which an experienced member of an organization gives advice and guidance to a less experienced member, and helps that person learn how to advance in the organization and in their career, is called:","options":["Diversity education","Mentoring","Multipronged training","Diversity awareness programs"],"answer":1,"why":"التعريف فيه عضو experienced يعطي advice and guidance لعضو less experienced ويساعده يتقدّم في المنظمة وفي الـ career، وهذا تعريف mentoring بالحرف. الخبير اسمه mentor والأقل خبرة اسمه protégé.","wrong":[{"i":0,"mis":"gen.neighbor","note":"diversity education تعلّم الناس كيف تنفهم التعليقات وكيف يحلّون سوء الفهم، وما فيها واحد خبير ماسك يد واحد جديد."},{"i":2,"mis":"gen.neighbor","note":"التدريب multipronged يعني أفلام ومواد وتمارين وrole-plays للكل، مو علاقة بين اثنين عشان التقدّم في المسار المهني."},{"i":3,"mis":"gen.neighbor","note":"برامج الـ awareness تخلّيك تنتبه لتحيّزاتك ولمنظورات غيرك، بس ما فيها نصيحة من خبير لأقل خبرة."}],"tests":["mentoring","mentor","protégé","encourage mentoring of employees with diverse backgrounds"]},{"n":402,"lo":"LO5-6","sec":"MGT102-CH5-S4","type":"term","topic":"quid-pro-quo-definition","stem":"According to the book, quid pro quo sexual harassment means:","options":["Telling lewd jokes or making sexual remarks that make work unpleasant","Asking or forcing sexual favors in return for a reward or to avoid a penalty","Knowingly denying diverse employees access to opportunities and outcomes","Systematically using information about others in ways that distort perceptions"],"answer":1,"why":"quid pro quo يعني «هذا مقابل هذا»: المتحرّش يطلب أو يجبر الموظف على sexual favors مقابل مكافأة (ترقية، زيادة، يحتفظ بوظيفته) أو عشان يتجنّب عقوبة زي التنزيل أو الفصل. الكاشف إن فيه مقايضة.","wrong":[{"i":0,"mis":"c5.quid-vs-hostile","note":"هذا وصف hostile work environment: نكت وتعليقات جنسية تخرّب جو الشغل، بدون أي مقايضة."},{"i":2,"mis":"gen.neighbor","note":"هذا تعريف overt discrimination من الدرس الثالث، حرمان متعمّد من الفرص، مو تحرّش جنسي."},{"i":3,"mis":"gen.neighbor","note":"هذا تعريف bias، ميل منهجي يطلّع إدراك غلط، وما له دخل بالتحرّش."}],"tests":["quid pro quo sexual harassment","hostile work environment sexual harassment"]},{"n":403,"lo":"LO5-6","sec":"MGT102-CH5-S4","type":"term","topic":"hostile-environment-definition","stem":"Which of the following best describes hostile work environment sexual harassment?","options":["Asking for sexual favors in return for a promotion or to avoid being fired","Sex-related jokes, remarks, or images that make the workplace unpleasant","Racist remarks and drawings that make the workplace hostile for a worker","Preconceived notions about the traits and behaviors of men and women"],"answer":1,"why":"hostile work environment sexual harassment يعني نكت فاحشة وتعليقات جنسية على المظهر وعرض مواد إباحية وأي تصرّف جنسي يخلّي بيئة الشغل unpleasant، وما فيه أي مقايضة. الكاشف: جو عام مزعج بسبب الجنس، مو صفقة.","wrong":[{"i":0,"mis":"c5.quid-vs-hostile","note":"هذا quid pro quo لأن فيه مقابل (ترقية أو تتجنّب الفصل)، والبيئة العدائية ما فيها أي مقايضة."},{"i":2,"mis":"gen.keyword","note":"كلمة hostile شدّتك، وصح المحاكم تعترف ببيئة عدائية بسبب العرق (قضية Tesla)، بس هذي عنصرية مو جنسية، فما تنحسب sexual harassment."},{"i":3,"mis":"gen.neighbor","note":"هذا تعريف gender schemas من الدرس الثالث، أفكار مسبقة في الراس عن الرجال والنساء، مو تصرّفات جنسية في الشغل."}],"tests":["hostile work environment sexual harassment","quid pro quo sexual harassment","hostile work environment harassment (non-sexual)"]},{"n":404,"lo":"LO5-6","sec":"MGT102-CH5-S4","type":"term","topic":"sexual-harassment-definition","stem":"Unwanted behavior of a sexual nature that can either influence job decisions or create a hostile workplace is generally called:","options":["Quid pro quo sexual harassment","Sexual harassment","Hostile work environment sexual harassment","Overt discrimination"],"answer":1,"why":"التعريف فيه «أو»: يأثّر على قرارات التوظيف (هذا شكل quid pro quo) أو يسوّي بيئة عدائية (هذا شكل hostile). المصطلح العام اللي يجمع الشكلين هو sexual harassment.","wrong":[{"i":0,"mis":"gen.partial","note":"quid pro quo يغطّي بس النص الأول (قرارات التوظيف)، والتعريف يشمل البيئة العدائية بعد."},{"i":2,"mis":"gen.keyword","note":"شفت كلمة hostile في السؤال فاخترته، بس هذا شكل واحد بس، والتعريف يغطّي الشكلين."},{"i":3,"mis":"gen.neighbor","note":"overt discrimination حرمان متعمّد من الفرص والنتائج، مو سلوك ذو طابع جنسي."}],"tests":["sexual harassment","two forms of sexual harassment"]},{"n":405,"lo":"LO5-5","sec":"MGT102-CH5-S4","type":"concept","topic":"steps-meaning","stem":"Which statement about the steps for managing diversity is correct according to the book?","options":["Encouraging flexibility means that employees should suppress their personal styles","Letting staff work from home or leave early for a religious holiday is flexibility","Tying managers' pay to diversity goals is an example of the diversity training step","Only employees who face discrimination themselves should speak up to challenge it"],"answer":1,"why":"الكتاب تحت encourage flexibility يقول المدير يتوقّع احتياجات الموظفين ويستجيب لها بمرونة، زي إنه يخلّي اللي عنده عيد ديني يطوّف ساعة الغدا ويطلع بدري. وflexible work hours وخيار الشغل من البيت وcafeteria-style benefit plans كلها أمثلة على المرونة بعد.","wrong":[{"i":0,"mis":"gen.reversed","note":"الكتاب يقول بالنص إن المرونة ما تعني إنك تكبت أسلوبك الشخصي (suppress their personal styles)، تعني تنفتح على الطرق الثانية بدون ما تحسّ بتهديد."},{"i":2,"mis":"c5.step-example-mix","note":"ربط أجر المدراء بأهداف التنوّع (مثال Coca-Cola) يتبع خطوة reward employees for effectively managing diversity، مو التدريب."},{"i":3,"mis":"gen.partial","note":"الكتاب يقول الموظف يتحدّى التمييز سواء كان موجّه له أو شافه على زميله، والإدارة العليا تبني ثقافة zero tolerance for discrimination."}],"tests":["encourage flexibility","religious holidays","option to work from home","suppress personal styles","reward employees for effectively managing diversity","empower employees to challenge discriminatory behaviors, actions, and remarks","zero tolerance for discrimination"]},{"n":406,"lo":"LO5-5","sec":"MGT102-CH5-S4","type":"concept","topic":"effective-mentoring-thomas","stem":"David Thomas studied the careers of underrepresented groups in corporate America. According to him, which statement about mentoring is true?","options":["It is mostly about passing on technical expertise and career advice","A close, supportive bond matters as much as advice and instruction","The protégé gives advice and guidance to a less experienced mentor","Most who reached high levels did it without mentors or contacts"],"answer":1,"why":"Thomas يقول الإرشاد الفعّال أكثر من تعليمات ونصايح وخبرة تقنية؛ هذي مهمة وضرورية، بس بنفس الأهمية علاقة high-quality قريبة وداعمة مع الـ protégé. الروابط العاطفية تخلّيه يقول مخاوفه بحرية وتبني ثقته.","wrong":[{"i":0,"mis":"gen.partial","note":"التعليمات والخبرة التقنية مهمة، بس Thomas يقول الإرشاد مو بس كذا، والعلاقة الداعمة equally important."},{"i":2,"mis":"c5.mentor-vs-protege","note":"عكست الأدوار: الـ mentor هو الخبير اللي يعطي النصيحة، والـ protégé هو الأقل خبرة اللي ياخذها."},{"i":3,"mis":"gen.reversed","note":"بالعكس، Thomas لقى إن أغلب الفئات الممثّلة تمثيل ناقص اللي وصلوا لمستويات عالية وصلوا بشبكة قوية من mentors and contacts."}],"tests":["effective mentoring","david thomas","underrepresented groups","solid network of mentors and contacts","mentor","protégé"]},{"n":407,"lo":"LO5-6","sec":"MGT102-CH5-S4","type":"concept","topic":"sexual-harassment-facts","stem":"Which statement about sexual harassment is consistent with the book?","options":["It is considered unethical, but courts do not treat it as illegal","It harms the people harassed, but not the organization's reputation","Managers must ensure no one engages in it, even unintentionally","Quid pro quo claims fall under the Equal Pay Act, not Title VII"],"answer":2,"why":"الكتاب يقول على المدير ethical obligation يتأكد إنه هو وزملاه وموظفينه ما يمارسون التحرّش أبداً، even unintentionally يعني حتى بدون قصد. والتحرّش مو بس غير أخلاقي، هو غير قانوني بعد.","wrong":[{"i":0,"mis":"gen.partial","note":"أخذت نص الحقيقة بس: الكتاب يقول not only unethical but also illegal، والمحاكم تعتبر البيئة العدائية غير قانونية."},{"i":1,"mis":"gen.partial","note":"الكتاب يقول التحرّش يضرّ اللي ينتحرّش بهم ويضرّ سمعة المنظمة بعد، ويقدر يكلّف المنظمات مليارات."},{"i":3,"mis":"c5.eeo-law-coverage","note":"ادعاءات quid pro quo تدخل تحت Title VII of the Civil Rights Act، والـ Equal Pay Act حقّه المساواة في الأجر بين الجنسين."}],"tests":["sexual harassment","unethical and illegal","ethical obligation","even unintentionally","damage to the organization's reputation","quid pro quo claims under title vii"]},{"n":408,"lo":"LO5-5","sec":"MGT102-CH5-S4","type":"scenario","topic":"awareness-frontline","stem":"The CEO of a large supermarket chain in Riyadh realizes that he is far removed from his entry-level cashiers and does not really know what they face each day. He spends a week working beside them to understand their challenges, attitudes, and perspectives, as if walking in their shoes. Which step for managing diversity is he mainly using?","options":["Increase diversity skills","Secure top management commitment","Increase diversity awareness","Encourage mentoring of diverse employees"],"answer":2,"why":"الكتاب تحت increase diversity awareness يقول كبار المدراء في المنظمات الكبيرة غالباً بعيدين عن موظفي الصف الأول، وبعضهم ياخذ خطوات ملموسة عشان يفهم خبراتهم ومواقفهم ومنظوراتهم. والهدف إنه يصير واعي بمنظور غيره ويحط نفسه مكانهم، وهذا الوعي بالتنوّع.","wrong":[{"i":0,"mis":"c5.awareness-vs-skills","note":"skills تركّز على التواصل الفعلي: أساليب الكلام واللغة ولغة الجسد وحل سوء الفهم، والـ CEO هنا يبي يفهم تجربتهم ومنظورهم."},{"i":1,"mis":"gen.keyword","note":"كلمة CEO ودّتك للإدارة العليا، بس التزام الإدارة العليا يعني يطوّرون القيم الأخلاقية الصحيحة والمواقف الموجّهة للأداء، والكتاب يحط مثال المدير اللي ينزل يفهم الصف الأول تحت awareness."},{"i":3,"mis":"c5.step-example-mix","note":"الإرشاد خبير يعطي نصيحة وتوجيه لواحد أقل خبرة عشان يتقدّم، والـ CEO هنا هو اللي يتعلّم منهم مو يرشدهم."}],"tests":["increase diversity awareness","top managers far removed from entry-level employees","mentally walk in other people's shoes","increase diversity skills","secure top management commitment"]},{"n":409,"lo":"LO5-5","sec":"MGT102-CH5-S4","type":"scenario","topic":"accuracy-of-perceptions","stem":"Faisal, a project manager at an engineering firm in Jeddah, formed a poor first impression of a new engineer on his team. Instead of acting on it, he holds off on judging her until he has gathered enough relevant information, and when her work proves his first impression wrong, he openly changes his view. Which step for managing diversity is Faisal practicing?","options":["Increase diversity awareness","Increase the accuracy of perceptions","Encourage mentoring of diverse employees","Increase diversity skills"],"answer":1,"why":"Faisal تجنّب الحكم السريع (snap judgment)، وانتظر لين جمع معلومات كافية وذات صلة، وغيّر رأيه لما جات أدلة تخالفه (disconfirming evidence). هذا بالضبط increase the accuracy of perceptions.","wrong":[{"i":0,"mis":"c5.step-example-mix","note":"awareness إنك تكتشف تحيّزاتك وتفهم منظورات غيرك عن طريق البرامج والتعامل معهم، بس اللي سوّاه Faisal بالنص (ما يحكم بسرعة، ينتظر معلومات كافية، ويغيّر رأيه مع الدليل) هو كلام الكتاب عن accuracy of perceptions."},{"i":2,"mis":"c5.step-example-mix","note":"الإرشاد علاقة خبير يعطي نصيحة وتوجيه لواحد أقل خبرة عشان يتقدّم، وFaisal هنا ما يرشد أحد، هو يراجع حكمه على الموظفة."},{"i":3,"mis":"c5.step-example-mix","note":"skills عن التواصل والتعامل اليومي (لغة، لغة جسد، سوء فهم)، وما لها علاقة بإنك تأجّل حكمك وتغيّره مع الدليل."}],"tests":["increase the accuracy of perceptions","snap judgments","disconfirming evidence"]},{"n":410,"lo":"LO5-6","sec":"MGT102-CH5-S4","type":"scenario","topic":"hostile-environment-scenario","stem":"At a logistics company in Dammam, a group of male workers keeps telling lewd jokes and making sexually oriented remarks about a male coworker's appearance. No one has asked him for anything or threatened his job, but the workplace has become offensive to him and his work is suffering. According to the book, this situation is best described as:","options":["Quid pro quo sexual harassment, since his job could suffer because of it","No sexual harassment, since the book says only women can be victims","Hostile work environment sexual harassment, with no exchange involved","Overt discrimination, since he is knowingly denied job opportunities"],"answer":2,"why":"نكت فاحشة وتعليقات جنسية على المظهر، وما فيه مقايضة، والجو صار مهين ويأثّر على شغله، فهذا hostile work environment. والكتاب يقول الضحية ممكن تكون من أي جنس، والمتحرّش مو لازم يكون من الجنس الثاني.","wrong":[{"i":0,"mis":"c5.quid-vs-hostile","note":"quid pro quo يحتاج مقايضة (سوّ كذا وإلا تنفصل)، والسؤال يقول واضح ما أحد طلب منه شي ولا هدّد وظيفته."},{"i":1,"mis":"gen.absolute","note":"صح النساء أكثر الضحايا، خصوصاً في المهن اللي يسيطر عليها الرجال، بس الكتاب يقول victims can be of any gender، فكون الضحية رجّال ما يلغي التحرّش."},{"i":3,"mis":"gen.neighbor","note":"overt discrimination حرمان متعمّد من الفرص والنتائج، وهنا ما أحد منعه من فرصة، المشكلة في الجو المهين."}],"tests":["hostile work environment sexual harassment","quid pro quo sexual harassment","victims of any gender","women are the most frequent victims"]},{"n":411,"lo":"LO5-6","sec":"MGT102-CH5-S4","type":"scenario","topic":"fair-complaint-procedure","stem":"At a hotel in AlUla, an employee tells HR that her supervisor has been sexually harassing her. The hotel has the case handled by a neutral third party, deals with it promptly and thoroughly, protects the employee, and makes sure the supervisor is also treated fairly while the facts are checked. Which step to eradicate sexual harassment is the hotel following?","options":["Develop and communicate a policy endorsed by top management","Use a fair complaint procedure to investigate the charges","Take corrective action as soon as possible","Provide harassment education and training to all members"],"answer":1,"why":"الأربع شروط كلها موجودة: طرف ثالث محايد، سرعة وشمول، حماية الضحية، ومعاملة عادلة للمتّهم، وهذي use a fair complaint procedure، الخطوة الثانية. والكاشف إنهم لسه يتحقّقون من الحقائق.","wrong":[{"i":0,"mis":"c5.harassment-steps","note":"السياسة (الخطوة الأولى) هي الوثيقة اللي فيها أمثلة السلوك وطريقة الإبلاغ والعقوبات، مو طريقة التحقيق في شكوى معيّنة."},{"i":2,"mis":"c5.harassment-steps","note":"الإجراء التصحيحي يجي بعد ما يثبت التحرّش، والفندق هنا لسه يتحقّق."},{"i":3,"mis":"c5.harassment-steps","note":"التدريب لكل الأعضاء بما فيهم المدراء خطوة رابعة منفصلة، والسيناريو عن التعامل مع شكوى."}],"tests":["fair complaint procedure","neutral third party","alleged harassers treated fairly","steps to eradicate sexual harassment","sexual harassment education and training"]},{"n":412,"lo":"LO5-5","sec":"MGT102-CH5-S4","type":"figure","topic":"table-5-4-not-a-step","stem":"Look at Table 5.4, Promoting the Effective Management of Diversity. Which of the following is NOT one of the steps listed in the table?","img":"img/mgt102/table-5-4.png","options":["Consider the numbers","Set hiring quotas for each underrepresented group","Empower employees to challenge discriminatory behaviors, actions, and remarks","Provide training, utilizing a multi-pronged, ongoing approach"],"answer":1,"why":"اقرأ الجدول: 11 بند وما فيها ولا بند عن hiring quotas. خطوة consider the numbers يعني تطالع أعداد النساء والأقليات في المناصب والمستويات والمواقع، ولو فيه نقص تفهم السبب وتحلّه، مو تفرض رقم.","wrong":[{"i":0,"mis":"gen.detail","note":"consider the numbers البند السابع بالنص؛ يمكن حسبته هو نفسه الحصص، بس معناه تطالع الأرقام وتفهم ليش فيه نقص، مو تفرض عدد."},{"i":2,"mis":"gen.detail","note":"هذا البند الثامن بالحرف: الموظفين يتحدّون التمييز في ثقافة zero tolerance، يمكن طوله خلّاك تشكّ فيه."},{"i":3,"mis":"gen.detail","note":"هذا البند العاشر: تدريب multipronged يعني أكثر من أداة (أفلام ومواد وتمارين وrole-plays)، و ongoing يعني مستمر مو مرّة وحدة."}],"tests":["table 5.4","steps in managing diversity effectively","consider the numbers","empower employees to challenge discriminatory behaviors, actions, and remarks","provide training utilizing a multipronged, ongoing approach"]},{"n":413,"lo":"LO5-5","sec":"MGT102-CH5-S4","type":"figure","topic":"evaluation-step","stem":"Look at Table 5.4. A manager at a telecom company in Riyadh relies on objective performance indicators whenever she can, because they are less open to bias. When she has to use subjective ratings, she makes sure enough time goes into them and that the raters are held accountable. Which item in the table is she applying?","img":"img/mgt102/table-5-4.png","options":["Increase the accuracy of perceptions","Consider the numbers","Pay close attention to how employees are evaluated","Reward employees for effectively managing diversity"],"answer":2,"why":"objective performance indicators لأنها less subject to bias، ولما ما تتوفّر: وقت واهتمام كافي، والمقيّمين accountable، وبدون معايير غامضة. هذا البند السادس pay close attention to how employees are evaluated.","wrong":[{"i":0,"mis":"c5.step-example-mix","note":"كلمة bias خلّتك تروح للإدراك، بس accuracy of perceptions عن الانفتاح على الآراء وتجنّب snap judgments، مو عن طريقة تقييم الأداء."},{"i":1,"mis":"c5.step-example-mix","note":"consider the numbers تعدّ النساء والأقليات في المناصب والمستويات، مو إنك تقيّم أداء كل موظف."},{"i":3,"mis":"c5.step-example-mix","note":"المكافأة زي ربط الأجر بأهداف التنوّع، وهذي غير التقييم العادل للأداء."}],"tests":["table 5.4","pay close attention to how employees are evaluated","objective performance indicators","evaluators held accountable"]},{"n":414,"lo":"LO5-5","sec":"MGT102-CH5-S4","type":"list","topic":"table-5-4-count-first","stem":"How many steps for promoting the effective management of diversity does the book list in Table 5.4, and which one comes first?","options":["10 steps, starting with securing top management commitment","11 steps, starting with increasing diversity awareness","11 steps, starting with securing top management commitment","12 steps, starting with considering the numbers"],"answer":2,"why":"Table 5.4 فيه 11 خطوة، وأولها secure top management commitment لأن التزام الإدارة العليا crucial لنجاح أي مبادرة تنوّع. احفظ 11، مو 10 ولا 12.","wrong":[{"i":0,"mis":"c5.steps-count","note":"10 هو عدد الأدوار في Table 5.2، مو خطوات Table 5.4."},{"i":1,"mis":"c5.steps-count","note":"العدد صح بس الأولى غلط: diversity awareness هي الخطوة الثالثة، والأولى التزام الإدارة العليا."},{"i":3,"mis":"c5.steps-count","note":"12 هو عدد مصادر التنوّع في Figure 5.1، و consider the numbers هي السابعة مو الأولى."}],"tests":["table 5.4","steps in managing diversity effectively","secure top management commitment"]},{"n":415,"lo":"LO5-6","sec":"MGT102-CH5-S4","type":"list","topic":"harassment-policy-contents","stem":"According to the book, a sexual harassment policy endorsed by top management should ban both forms of harassment and contain four things. Which of the following is NOT one of them?","options":["Examples of the types of behavior that are unacceptable","A procedure employees can use to report harassment","A neutral third party who manages every complaint","A discussion of the disciplinary actions that will be taken"],"answer":2,"why":"محتويات السياسة الأربعة: أمثلة السلوك غير المقبول، طريقة الإبلاغ، الإجراءات التأديبية، والتزام بالتثقيف والتدريب. الطرف الثالث المحايد من شروط fair complaint procedure في الخطوة الثانية، مو من السياسة.","wrong":[{"i":0,"mis":"c5.harassment-steps","note":"أمثلة السلوك غير المقبول أول عنصر في السياسة بالنص."},{"i":1,"mis":"c5.harassment-steps","note":"طريقة يستخدمها الموظفين للإبلاغ عنصر ثاني في السياسة، لا تخلطها مع إجراء التحقيق في الشكوى."},{"i":3,"mis":"c5.harassment-steps","note":"شرح الإجراءات التأديبية عنصر ثالث في السياسة، موجود بالنص."}],"tests":["sexual harassment policy","fair complaint procedure","neutral third party","steps to eradicate sexual harassment"]},{"n":416,"lo":"LO5-6","sec":"MGT102-CH5-S4","type":"tf","topic":"corrective-action-severity","stem":"According to the book, once sexual harassment has been established, the corrective action must always be to fire the harasser, whatever the severity of the case.","options":["True","False"],"answer":1,"why":"غلط. الكتاب يقول خذ corrective action بأسرع وقت، والإجراء يختلف حسب الـ severity. ولما يكون التحرّش extensive أو prolonged أو quid pro quo أو مرفوض بشدّة، الإجراء may include firing يعني ممكن يوصل للفصل، مو لازم. كلمة always هي الفخ.","wrong":[{"i":0,"mis":"gen.absolute","note":"كلمة always و whatever the severity خلّت الجملة مطلقة، والكتاب يقول may include firing في الحالات الشديدة بس."}],"tests":["corrective action","severity of harassment","steps to eradicate sexual harassment"]},{"n":417,"lo":"LO5-5","sec":"MGT102-CH5-S4","type":"vocab","topic":"vocab-rectify","stem":"In the sentence \"In a culture with zero tolerance for discrimination, employees who see a coworker being treated unfairly should speak up and rectify the situation,\" the word rectify most nearly means:","options":["Accept it as a normal part of work","Correct it and make it right","Report it to people outside the company","Leave it for top managers to handle"],"answer":1,"why":"rectify يعني تصحّح الغلط وترجّع الأمور لوضعها الصح. وهذي فكرة خطوة empower employees: أي موظف يشوف تمييز، عليه أو على غيره، يتكلّم ويصحّح الوضع، والثقافة فيها zero tolerance.","wrong":[{"i":0,"mis":"gen.vocab","note":"هذا عكس الجملة تماماً، zero tolerance يعني ما نقبل التمييز أبداً."},{"i":2,"mis":"gen.vocab","note":"rectify مو «يبلّغ برّا»، هي تصحيح الوضع نفسه داخل الشغل."},{"i":3,"mis":"gen.vocab","note":"الجملة تقول الموظف نفسه يتكلّم ويصحّح، مو يترك الموضوع للإدارة العليا."}],"tests":["rectify","empower employees to challenge discriminatory behaviors, actions, and remarks","zero tolerance for discrimination"]},{"n":418,"lo":"LO5-6","sec":"MGT102-CH5-S4","type":"vocab","topic":"vocab-subtle","stem":"In the sentence \"Compared with quid pro quo harassment, hostile work environment sexual harassment can be more subtle,\" the word subtle most nearly means:","options":["More extreme and easier for everyone to see","Less obvious and harder to notice","Less harmful to the person who faces it","Shorter and over more quickly"],"answer":1,"why":"subtle يعني خفي ومو واضح. الكتاب يقابل بين quid pro quo (the more extreme type وما يخلّي أي شك) و hostile (ممكن يكون more subtle).","wrong":[{"i":0,"mis":"c5.quid-vs-hostile","note":"هذا وصف quid pro quo (the more extreme type)، عكس subtle تماماً."},{"i":2,"mis":"gen.vocab","note":"subtle ما تعني أقل ضرر، الكتاب يقول البيئة العدائية تعيق قدرة الموظف على شغله وغير قانونية."},{"i":3,"mis":"gen.vocab","note":"subtle ما لها علاقة بالمدة، هي عن قد إيش الشي واضح."}],"tests":["subtle","hostile work environment sexual harassment","quid pro quo sexual harassment"]},{"n":419,"lo":"LO5-6","sec":"MGT102-CH5-S4","type":"vocab","topic":"vocab-eradicate","stem":"What does the word \"eradicate\" mean? (as in: \"Managers, in collaboration with the HR staff, have an ethical obligation to eradicate sexual harassment.\")","options":["يحقّق فيه ويفحصه","يقضي عليه من جذوره","يبلّغ عنه بشكل رسمي","يخفّف منه شوي"],"answer":1,"why":"eradicate يعني يقضي على الشي ويشيله من جذوره لين ما يبقى منه شي. والكتاب يعطي المدير، مع موظفي الـ HR، أربع خطوات يقضي فيها على التحرّش: سياسة، إجراء شكاوى عادل، إجراء تصحيحي سريع، وتدريب.","wrong":[{"i":0,"mis":"gen.vocab","note":"يحقّق هي investigate، وهذي جزء من الخطوة الثانية مو معنى eradicate."},{"i":2,"mis":"gen.vocab","note":"يبلّغ هي report، كلمة ثانية من نفس القسم."},{"i":3,"mis":"gen.vocab","note":"eradicate أقوى بكثير من التخفيف، هي قضاء كامل على الشي."}],"tests":["eradicate","steps to eradicate sexual harassment"]},{"n":420,"lo":"LO5-6","sec":"MGT102-CH5-S4","type":"vocab","topic":"vocab-alleged","stem":"What does the word \"alleged\" mean? (as in: \"The procedure should ensure that alleged harassers are fairly treated.\")","options":["مُدان وثبتت عليه التهمة","متّهم وما ثبت عليه شي","ضحية تعرّض للأذى","شاهد شاف اللي صار"],"answer":1,"why":"alleged يعني مزعوم أو متّهم: الناس يقولون سوّاها بس لسه ما ثبت عليه. وعشان كذا إجراء الشكاوى العادل لازم يعامل الـ alleged harassers بعدل بعد.","wrong":[{"i":0,"mis":"gen.vocab","note":"مُدان عكسها، alleged يعني لسه ما ثبت عليه شي."},{"i":2,"mis":"gen.vocab","note":"الضحية هي victim، والجملة تتكلّم عن المتّهم بالتحرّش."},{"i":3,"mis":"gen.vocab","note":"الشاهد witness، وما له علاقة بكلمة alleged."}],"tests":["alleged","fair complaint procedure"]},{"n":901,"lo":"LO5-4","sec":"CASE","type":"case","topic":"salience-effect","stem":"Which concept from the chapter best explains how Khalid pays attention to Reem and judges her work?","caseId":"C5-A","options":["The social status effect","Overt discrimination","The salience effect","A stereotype"],"answer":2,"why":"Reem هي المرأة الوحيدة بين ستة رجال، يعني بارزة ومختلفة عن الجروب. Khalid عيونه عليها دايم، يمدحها زيادة لما تنجح ويقسى عليها زيادة لما تغلط — وهذا salience effect: انتباه زايد على اللي بارز وتقييم متطرّف بالاتجاهين.","wrong":[{"i":0,"mis":"c5.status-vs-salience","note":"تحسبه social status effect لأنه تحيّز في الإدراك، بس هذا عن مكانة الشخص العالية أو الواطية، وقصة Reem ما فيها مكانة، فيها إنها مختلفة وبارزة."},{"i":1,"mis":"c5.overt-vs-unintended","note":"ممكن تختاره لأن فيه معاملة مو عادلة، بس overt discrimination يعني يحرمها من فرص عن علم وقصد، وKhalid ما حرمها شي وتصرّفه بدون قصد — حتى إنه يمدحها."},{"i":3,"mis":"c5.stereotype-vs-bias","note":"الـ stereotype اعتقاد مبسّط عن صفات فئة كاملة، والقصة ما فيها أي اعتقاد عن صفات النساء — فيها بس انتباه زايد وتقييم متطرّف."}],"tests":["salience effect","social status effect","overt discrimination","stereotype"]},{"n":902,"lo":"LO5-2","sec":"CASE","type":"case","topic":"disturbance-handler-role","stem":"When Khalid stopped the senior dispatcher's behaviour on the same day, he was acting in the ____ role, which is one of the ____ roles in Table 5.2.","caseId":"C5-A","options":["disturbance handler; decisional","disturbance handler; interpersonal","monitor; informational","leader; interpersonal"],"answer":0,"why":"Khalid أول ما عرف بموضوع الموظف الكبير اللي يمنع البرنامج عن Reem، وقفه في نفس اليوم — تحرّك سريع يصلّح عدم المساواة ويوقف السلوك التمييزي، وهذا disturbance handler، وهو من الـ decisional roles (الأربعة: entrepreneur, disturbance handler, resource allocator, negotiator).","wrong":[{"i":1,"mis":"c5.role-type-count","note":"الدور صح بس النوع غلط: disturbance handler من الـ decisional roles، والـ interpersonal هي figurehead و leader و liaison بس."},{"i":2,"mis":"c5.role-duty-mix","note":"الـ monitor يقيّم قد إيش الكل ينعاملون بعدل وبس، وKhalid ما وقف عند التقييم — تحرّك ووقف الغلط بنفس اليوم."},{"i":3,"mis":"c5.role-duty-mix","note":"الـ leader يكون قدوة ويحط سياسات وإجراءات عامة للعدل، وKhalid ما حط سياسة جديدة، صلّح موقف واحد بسرعة."}],"tests":["disturbance handler","decisional roles","monitor","leader","managerial roles"]},{"n":903,"lo":"LO5-3","sec":"CASE","type":"case","topic":"distributive-vs-procedural-justice","stem":"Complete the sentence using the chapter's terms: The way Khalid decided the raises reflects ____, and Fahad's larger raise ____.","caseId":"C5-A","options":["procedural justice; violates distributive justice","distributive justice; is consistent with procedural justice","overt discrimination; violates distributive justice","procedural justice; is consistent with distributive justice"],"answer":3,"why":"طريقة القرار نفسها — راجع السجلات بعناية، وحسب حساب أجهزة الـ GPS الخربانة، وتجاهل العمر والـ ethnicity — هي أمثلة الكتاب الثلاثة على procedural justice. وزيادة Fahad الأكبر ما فيها ظلم لأن مساهمته أكبر بوضوح، وdistributive justice مو معناها الكل ياخذ نفس الشي.","wrong":[{"i":0,"mis":"c5.distributive-equal-outcomes","note":"تحسب distributive justice يعني الكل ياخذ نفس الزيادة، بس الكتاب يقول اللي يساهم أكثر بشكل واضح يستاهل نتيجة أحسن، وFahad كذا."},{"i":1,"mis":"c5.distributive-vs-procedural","note":"عكست المبدأين: طريقة اتخاذ القرار (الـ how) = procedural، والنتيجة اللي كل واحد ياخذها (الـ what) = distributive."},{"i":2,"mis":"c5.distributive-equal-outcomes","note":"تحسب إعطاء Fahad زيادة أكبر من الباقين تمييز، بس overt discrimination يعني حرمان عن علم وقصد بسبب صفات شخصية، وKhalid تجاهل العمر والـ ethnicity وعطى على حسب الأداء."}],"tests":["procedural justice","distributive justice","overt discrimination"]},{"n":904,"lo":"LO5-1","sec":"CASE","type":"case","topic":"glass-ceiling","stem":"Which chapter term best describes what Mona's numbers reveal about the top of the company?","caseId":"C5-B","options":["Overt discrimination","A glass ceiling","Distributive justice","The social status effect"],"answer":1,"why":"Mona لقت النساء يوصلون لرئاسة الأقسام (40%) بس صفر في المناصب العليا الـ12، ومافي قاعدة مكتوبة ولا أحد من المدراء يقصد يوقّفهم — حاجز ما ينشاف يمنع النساء والأقليات من الترقية للمناصب العليا، وهذا هو glass ceiling.","wrong":[{"i":0,"mis":"c5.overt-vs-unintended","note":"ممكن تحسبه تمييز صريح لأن النساء ما يوصلون للقمّة، بس overt discrimination يعني حرمان عن علم وقصد (knowingly and willingly)، والقصة تقول ولا واحد من المدراء يقصد يوقّف النساء — الأرقام تكشف نمط بس، وحاجز ما ينشاف قدّام المناصب العليا = glass ceiling."},{"i":2,"mis":"gen.keyword","note":"شفت موضوع الترقيات وتذكرت إن distributive justice عن توزيع الرواتب والترقيات بعدل، بس الأرقام ما تكشف عدل، تكشف حاجز ما ينشاف يوقّف النساء تحت القمّة، واسمه glass ceiling."},{"i":3,"mis":"gen.neighbor","note":"ربطت كلمة 'top' بالمكانة، بس social status effect إنك تشوف صاحب المكانة العالية أحسن من غيره — انحياز في إدراك أشخاص، مو اسم الحاجز اللي يسد طريق الترقية للقمّة."}],"tests":["glass ceiling","overt discrimination"]},{"n":905,"lo":"LO5-5","sec":"CASE","type":"case","topic":"diversity-steps-numbers-mentoring","stem":"Mona's two actions (counting women and men at each job level, then the pairing program) match which steps in Table 5.4, in order?","caseId":"C5-B","options":["Pay close attention to how employees are evaluated; encourage mentoring","Consider the numbers; provide ongoing training","Consider the numbers; encourage mentoring","Increase diversity awareness; encourage mentoring"],"answer":2,"why":"Mona عدّت كم امرأة وكم رجل في كل مستوى وظيفي — هذي خطوة Consider the numbers. وبعدها ربطت كل رئيسة قسم جديدة بمدير عام خبير ينصحها ويعرّفها على ناس ويبني معها علاقة داعمة — وهذا Encourage mentoring.","wrong":[{"i":0,"mis":"c5.step-example-mix","note":"خطوة التقييم عن الاعتماد على مؤشرات أداء موضوعية ومحاسبة المقيّمين، وMona ما لمست طريقة التقييم — هي عدّت الناس في كل مستوى."},{"i":1,"mis":"c5.mentor-vs-protege","note":"حصرت الإرشاد في تعليم ونصايح فحسبته تدريب، بس التدريب يكون للكل بأفلام وتمارين وrole-plays، أما خبير مع شخص أقل خبرة وعلاقة قريبة داعمة بينهم فهذا mentoring."},{"i":3,"mis":"c5.step-example-mix","note":"الـ diversity awareness إنك تكتشف تحيّزاتك وتفهم وجهات نظر غيرك، وعدّ الموظفين في كل مستوى خطوة ثانية اسمها Consider the numbers."}],"tests":["consider the numbers","encourage mentoring","mentoring"]},{"n":906,"lo":"LO5-6","sec":"CASE","type":"case","topic":"quid-pro-quo-vs-hostile","stem":"Which option correctly classifies the complaint from each hotel?","caseId":"C5-B","options":["Jeddah: hostile work environment; Abha: quid pro quo","Jeddah: quid pro quo; Abha: hostile work environment","Jeddah: hostile work environment; Abha: hostile work environment","Jeddah: quid pro quo; Abha: not sexual harassment"],"answer":1,"why":"في جدة المشرف ربط الترقية بقبول تحرّش جنسي — مقايضة واضحة = quid pro quo. وفي أبها مافي مقابل، بس نكت وتعليقات جنسية خلّت الشغل بيئة مسيئة يكرهون يجونها وتعطّلهم عن شغلهم = hostile work environment.","wrong":[{"i":0,"mis":"c5.quid-vs-hostile","note":"عكستهم: اللي فيه ترقية مقابل شي جنسي هو quid pro quo، واللي جوّ عام من نكت وتعليقات هو hostile work environment."},{"i":2,"mis":"c5.quid-vs-hostile","note":"شفت سلوك جنسي في الفندقين وسمّيتهم الاثنين hostile work environment، بس في جدة الترقية مربوطة بقبول التحرّش — مقايضة = quid pro quo، وأبها بس هي البيئة المسيئة."},{"i":3,"mis":"gen.partial","note":"تحسب التحرّش لازم يكون فيه طلب أو مقابل، بس الكتاب يقول النكت والتعليقات الجنسية عن الشكل اللي تخرّب بيئة الشغل هي تحرّش جنسي من نوع hostile work environment."}],"tests":["quid pro quo sexual harassment","hostile work environment sexual harassment","sexual harassment"]},{"n":951,"lo":"LO5-5","sec":"MGT102-CH5-S4","type":"list","topic":"diversity-awareness-goals","stem":"Diversity awareness programs often have several goals. Which of the following is NOT one of these goals, according to the book?","options":["Uncovering personal biases and stereotypes","Overturning inaccurate stereotypes and beliefs about groups","Asking members to drop their personal styles and follow the majority","Providing members with accurate information about diversity"],"answer":2,"why":"الكتاب يعطي 6 أهداف لبرامج الوعي، كلها تدور حول معرفة تحيّزاتك وفهم الناس الثانيين. أما التخلّي عن أسلوبك الشخصي فالكتاب يقول العكس: المرونة ما تعني تكبت أسلوبك، بس تكون منفتح على غيرك.","wrong":[{"i":0,"mis":"gen.detail","note":"كشف التحيّزات والصور النمطية الشخصية هدف صريح من الستة، يمكن نسيته من القائمة."},{"i":1,"mis":"gen.detail","note":"قلب الصور النمطية الغلط عن المجموعات هدف من أهداف برامج الوعي، مو برّاها."},{"i":3,"mis":"c5.awareness-vs-skills","note":"يمكن حسبت المعلومات الدقيقة تبع التدريب على المهارات، بس هي أول هدف في قائمة الوعي."}],"tests":["diversity awareness programs","increase diversity awareness","encourage flexibility"]},{"n":952,"lo":"LO5-5","sec":"MGT102-CH5-S4","type":"term","topic":"diversity-awareness-programs","stem":"Programs that try to make managers and workers more aware of (1) their own attitudes, biases, and stereotypes and (2) the different perspectives of diverse coworkers and customers are called:","options":["Diversity awareness programs","Diversity skills programs","Mentoring programs","Employee resource groups"],"answer":0,"why":"diversity awareness programs تزيد وعيك بشيئين: مواقفك وتحيّزاتك وصورك النمطية، ومنظور الناس المختلفين عنك. الكلمة المفتاح هنا aware.","wrong":[{"i":1,"mis":"c5.awareness-vs-skills","note":"المهارات عن التعامل والتواصل الفعلي مع الناس المختلفين، مو عن وعيك بتحيّزاتك."},{"i":2,"mis":"gen.neighbor","note":"mentoring يعني شخص خبير ينصح ويوجّه شخص أقل خبرة، ما له علاقة بكشف التحيّزات."},{"i":3,"mis":"gen.neighbor","note":"employee resource groups مجموعات يكوّنها الموظفين عشان الشمول، مو برامج وعي تنظّمها الشركة."}],"tests":["diversity awareness programs","diversity skills"]},{"n":953,"lo":"LO5-5","sec":"MGT102-CH5-S4","type":"concept","topic":"diversity-education","stem":"According to the book, diversity education mainly helps managers and employees to:","options":["Accept different ways of working without feeling threatened by them","Understand how people read certain comments and fix misunderstandings","Count women and minorities at each level to spot underrepresentation","Walk in other people's shoes to uncover their own hidden biases"],"answer":1,"why":"diversity education جزء من خطوة increase diversity skills: يفهّمك كيف الناس ممكن يفسّرون تعليقات معيّنة، ويعلّمك تحلّ سوء الفهم أول بأول بدل ما يكبر.","wrong":[{"i":0,"mis":"c5.awareness-vs-skills","note":"هذا وصف encourage flexibility، تكون منفتح على الطرق المختلفة، مو التعليم عن تفسير التعليقات."},{"i":2,"mis":"c5.step-example-mix","note":"عدّ النساء والأقليات في كل مستوى هو خطوة consider the numbers، خطوة ثانية."},{"i":3,"mis":"c5.awareness-vs-skills","note":"هذا من أهداف برامج الوعي (awareness)، بينما diversity education تبع المهارات."}],"tests":["diversity education","increase diversity skills"]},{"n":954,"lo":"LO5-5","sec":"MGT102-CH5-S4","type":"scenario","topic":"encourage-flexibility","stem":"A hospital in Dammam lets each employee choose, from a menu of benefits, the ones that fit their needs (for example, childcare support for one nurse and extra health coverage for another). It also lets some staff work from home on certain days. Which step for managing diversity is the hospital following?","options":["Increase diversity skills","Pay close attention to how members are evaluated","Increase diversity awareness","Encourage flexibility"],"answer":3,"why":"الكتاب يعطي أمثلة على encourage flexibility: flexible work hours و option to work from home و cafeteria-style benefit plans (كل موظف يختار المزايا اللي تناسبه). المفتاح: المدير يتأقلم مع احتياجات الموظفين المختلفة.","wrong":[{"i":0,"mis":"c5.awareness-vs-skills","note":"المهارات عن التواصل والتعامل مع ناس مختلفين، مو عن المزايا وأماكن العمل."},{"i":1,"mis":"c5.step-example-mix","note":"خطوة التقييم عن objective performance indicators، والمستشفى هنا ما يقيّم أحد."},{"i":2,"mis":"c5.awareness-vs-skills","note":"الوعي عن معرفة تحيّزاتك ومنظور غيرك، مو عن تعديل المزايا حسب احتياج كل موظف."}],"tests":["cafeteria-style benefit plans","encourage flexibility","option to work from home"]},{"n":955,"lo":"LO5-5","sec":"MGT102-CH5-S4","type":"scenario","topic":"opt-out-approach","stem":"A telecom company in Riyadh used to ask employees to put themselves forward for management jobs, and few women did. Now it announces that everyone with the required experience and accomplishments will be considered unless they ask to be left out. This change is best described as:","options":["Replacing an opt-in method with an opt-out approach","Replacing an opt-out method with an opt-in approach","Pairing each woman with a mentor in senior management","Relying on objective indicators instead of vague standards"],"answer":0,"why":"قبل كان لازم الموظف يرشّح نفسه (opt-in)، الحين الكل داخل الترشيح إلا اللي يطلب يطلع (opt-out). والكتاب يقول الناس أقل احتمال يفوّتون فرصة لو لازم ينسحبون منها بنفسهم.","wrong":[{"i":1,"mis":"gen.reversed","note":"قلبت الاتجاه: الطريقة القديمة (رشّح نفسك) هي opt-in، والجديدة (الكل داخل إلا اللي ينسحب) هي opt-out."},{"i":2,"mis":"c5.step-example-mix","note":"mentoring خطوة ثانية، والشركة هنا ما ربطت أحد بمرشد، بس غيّرت طريقة الترشيح."},{"i":3,"mis":"c5.step-example-mix","note":"المؤشرات الموضوعية حل لمشكلة التقييم الغامض، مو لمشكلة إن النساء ما يرشّحون نفسهم."}],"tests":["opt-out approach","opt-in method","consider the numbers"]},{"n":956,"lo":"LO5-2","sec":"MGT102-CH5-S2","type":"term","topic":"employee-resource-groups","stem":"The CEO of a hospital group in Jeddah invites employees to form and join groups, such as a women's professional network and a network for employees with disabilities, to promote inclusion. He also takes part in these groups himself. The book calls such groups:","options":["Diversity awareness programs","Cross-functional interview teams","Employee resource groups","Advocacy groups"],"answer":2,"why":"employee resource groups مجموعات يكوّنها الموظفين وينضمّون لها عشان يعزّزون الشمول (inclusion)، زي اللي في Stryker. ولما المدير يشارك فيها بنفسه يصير role model لتنفيذييه.","wrong":[{"i":0,"mis":"gen.neighbor","note":"برامج الوعي تدريب تنظّمه الشركة عشان تكشف التحيّزات، مو مجموعات يكوّنها الموظفين."},{"i":1,"mis":"gen.neighbor","note":"الفريق متعدّد الأقسام يجتمع بعد المقابلات عشان يقلّل التحيّز في التوظيف، مو مجموعة شمول."},{"i":3,"mis":"gen.keyword","note":"advocacy groups جماعات ضغط برّا الشركة (زي اللي تضغط على صناعة الترفيه)، مو مجموعات موظفين داخل المنظمة."}],"tests":["employee resource groups","role model","inclusion"]},{"n":957,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"list","topic":"cei-criteria","stem":"The Corporate Equality Index (CEI), published every year by the Human Rights Campaign Foundation, rates employers on four key components. Which of the following is NOT one of them?","options":["Non-discrimination policies across business entities","Accessible workplaces for employees with disabilities","Equitable benefits for LGBTQ workers and their families","A commitment to corporate social responsibility"],"answer":1,"why":"معايير CEI الأربعة: non-discrimination policies، و equitable benefits، و inclusive organizational culture، و corporate social responsibility. موضوع الإعاقة يخص مؤشر ثاني اسمه Disability Equality Index.","wrong":[{"i":0,"mis":"gen.detail","note":"سياسات عدم التمييز عبر وحدات الشركة هي أول معيار من الأربعة."},{"i":2,"mis":"gen.detail","note":"المزايا العادلة للموظفين وعوائلهم معيار من الأربعة، يمكن نسيته."},{"i":3,"mis":"gen.detail","note":"يمكن حسبت المسؤولية الاجتماعية برّا الموضوع، بس هي المعيار الرابع في القائمة."}],"tests":["corporate equality index","cei rating criteria","disability equality index"]},{"n":958,"lo":"LO5-6","sec":"MGT102-CH5-S4","type":"concept","topic":"metoo-purple-campaign","stem":"Which statement about the #MeToo movement and The Purple Campaign is correct according to the book?","options":["#MeToo began in 2020, the year Harvey Weinstein was convicted in New York.","The Purple Campaign is the social media movement that began after the Weinstein accusations.","The Purple Campaign is a federal law requiring harassment training in all companies.","#MeToo began in late 2017, and its hashtag was used over 12 million times in 24 hours."],"answer":3,"why":"#MeToo بدأت أواخر 2017 بعد اتهامات Weinstein، والهاشتاق انستخدم أكثر من 12 مليون مرة في أول 24 ساعة. أما The Purple Campaign فهي منظمة تعالج التحرّش بسياسات شركات أقوى وقوانين أفضل.","wrong":[{"i":0,"mis":"gen.detail","note":"2020 سنة إدانة Weinstein، مو سنة بداية الحركة (أواخر 2017)."},{"i":1,"mis":"gen.neighbor","note":"خلطت بين الاثنين: حركة السوشال ميديا هي #MeToo، و Purple Campaign منظمة."},{"i":2,"mis":"gen.neighbor","note":"Purple Campaign منظمة تسعى لقوانين أفضل، هي نفسها مو قانون."}],"tests":["#metoo movement","the purple campaign","sexual harassment"]},{"n":959,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"term","topic":"dei-and-b","stem":"The book has a recurring feature called \"Focus on DEI&B.\" What do the letters DEI&B stand for?","options":["Diversity, Equity, Inclusion & Belonging","Disability, Equity, Inclusion & Benchmarking","Diversity, Equality, Integration & Benefits","Diversity, Ethics, Inclusion & Background"],"answer":0,"why":"DEI&B = Diversity, Equity, Inclusion & Belonging (اسم الإطار اللي في ملخّص الفصل وقال احفظه). وفي Case in the News عن Nike يجي DEI بدون B، والكتاب يكتبه صريح: diversity, equity, and inclusion — يعني أول ثلاث حروف مؤكّدة من الفصل، والـ B = Belonging.","wrong":[{"i":1,"mis":"gen.neighbor","note":"خلطت مع Disability Equality Index (أداة benchmarking في الفصل) لأن حروفه قريبة، بس D هنا Diversity زي ما يجي في DEI بقصة Nike."},{"i":2,"mis":"gen.vocab","note":"Equality و Integration كلمات قريبة بالمعنى، بس الكتاب يقول Equity و Inclusion."},{"i":3,"mis":"gen.keyword","note":"Ethics و Background كلمات من الفصل (ethical imperative و socioeconomic background) بس مو هي الاختصار."}],"tests":["dei&b","diversity, equity, inclusion & belonging"]},{"n":960,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"list","topic":"latino-contributions","stem":"The \"Focus on DEI&B\" feature gives four ways Hispanics and Latinos contribute to the U.S. economy. Which of the following is NOT one of them?","options":["Higher labor-force participation from a relatively young population","Starting new employer businesses at a higher-than-average rate","Faster population growth caused mainly by immigration, not births","Cultural agility that comes from navigating two or more cultures"],"answer":2,"why":"النمو السريع صحيح، بس الكتاب يقول السبب الأساسي معدّل المواليد الأعلى، والهجرة لها دور بس. المساهمات الأربع: نمو أسرع، مشاركة أعلى في العمل، ريادة أعمال (52% من new employer businesses في 2020)، و cultural agility.","wrong":[{"i":0,"mis":"gen.detail","note":"المشاركة الأعلى في سوق العمل لأن السكان صغار بالعمر مساهمة من الأربع."},{"i":1,"mis":"gen.detail","note":"ريادة الأعمال مساهمة صريحة: اللاتينيون 52% من new employer businesses في 2020."},{"i":3,"mis":"gen.detail","note":"cultural agility من التنقّل بين ثقافتين أو أكثر هي المساهمة النوعية الرابعة."}],"tests":["latino contributions","cultural agility","labor-force participation","population growth"]},{"n":961,"lo":"LO5-1","sec":"MGT102-CH5-S1","type":"list","topic":"census-race-categories","stem":"In the 2020 census, the U.S. Census Bureau distinguished among six races. Which of the following is NOT one of these six races?","options":["Asian","Hispanic or Latino","American Indian or Alaska Native","Native Hawaiian or Other Pacific Islander"],"answer":1,"why":"الأعراق الستة: White، و Black or African American، و American Indian or Alaska Native، و Asian، و Native Hawaiian or Other Pacific Islander، و Some Other Race. أما Hispanic or Latino فالتعداد يعامله كـ ethnicity مو race.","wrong":[{"i":0,"mis":"c5.race-ethnicity-ses","note":"يمكن حسبت Asian أصل وطني يعني ethnicity، بس هو عرق من الستة."},{"i":2,"mis":"gen.detail","note":"American Indian or Alaska Native عرق من الستة في التعداد."},{"i":3,"mis":"c5.race-ethnicity-ses","note":"يمكن حسبت Pacific Islander انتماء جغرافي يعني ethnicity، بس الكتاب يحطه ضمن الأعراق الستة."}],"tests":["race","ethnicity","census race categories"]}]};
